/**
 * dsh-theme-vivid — Client-Haelfte (Settings-Zeile "Color theme").
 *
 * Wird als Lazy-CJS-Bundle vom Modulsystem geladen:
 *   window.__ModuleLoader__.load({ id, factory })
 * Die Palette selbst liegt als CSS in THEMES (build.mjs setzt sie ein).
 *
 * Die Auswahl wird in localStorage gemerkt und beim naechsten Start sofort
 * angewendet; sie gewinnt damit gegen die im Profil konfigurierte Palette.
 */
window.__ModuleLoader__.load({
  id: "dsh-theme-vivid",
  factory: (require) => {
    var module = { exports: {} }
    var exports = module.exports

    const React = require("react")
    const THEMES = {"arctic":"/* ===== DSH Vivid Theme: Arctic =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: ARCTIC  —  Eiscyan auf kuehlem Stahl, knackig und klar\n   Hoher Kontrast ohne Blendeffekt: fast weisse Schrift, cyanfarbene\n   Akzente. Klarster Kandidat fuer helle Raeume und grosse Monitore.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #0b1114;\n  --dsw-alias-bg-layer-1: #10181c;\n  --dsw-alias-bg-layer-2: #152026;\n  --dsw-alias-bg-layer-3: #1c2931;\n  --dsw-alias-bg-overlay: #070d10f2;\n  --dsw-alias-bg-mask-1: #070d10b3;\n  --dsw-alias-bg-mask-2: #070d10d9;\n  --dsw-alias-bg-mask-3: #070d10f2;\n  --dsw-alias-bg-skeleton: #182429;\n\n  /* Linien */\n  --dsw-alias-border-l1: #8fd8e829;\n  --dsw-alias-border-l2: #8fd8e838;\n  --dsw-alias-border-l3: #8fd8e84d;\n  --dsw-alias-border-l4: #8fd8e86b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #e3eef2;\n  --dsw-alias-label-primary-bluish: #dceff7;\n  --dsw-alias-label-primary-dimmed: #bfd0d6;\n  --dsw-alias-label-secondary: #a5b8bf;\n  --dsw-alias-label-tertiary: #7f929a;\n  --dsw-alias-label-caption: #6b7d85;\n  --dsw-alias-label-dimmed: #586a71;\n  --dsw-alias-link: #86e2f0;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #5fd8e8;\n  --dsw-alias-brand-primary-invert: #0b1114;\n  --dsw-alias-brand-text: #a3eef7;\n  --dsw-alias-interactive-bg-hover: #5fd8e814;\n  --dsw-alias-interactive-bg-active: #5fd8e822;\n  --dsw-alias-interactive-bg-hover-accent: #5fd8e826;\n  --dsw-alias-button-primary-fill: #35bccd;\n  --dsw-alias-button-primary-hover: #4fd2e2;\n  --dsw-alias-button-ghost-active-fill: #5fd8e81f;\n  --dsw-alias-button-ghost-active-border: #5fd8e847;\n  --dsw-alias-button-ghost-active-hover: #5fd8e82e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #5fd8e80f;\n  --dsw-alias-markdown-code-block-banner: #5fd8e81a;\n  --dsw-alias-markdown-inline-code: #86e6f221;\n  --dsw-alias-markdown-citation: #5fd8e83d;\n  --dsw-alias-markdown-tag: #5fd8e82b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #4fd6b0;\n  --dsw-alias-state-success-secondary: #4fd6b026;\n  --dsw-alias-state-success-tertiary: #4fd6b014;\n  --dsw-alias-state-warn-primary: #f2cf72;\n  --dsw-alias-state-warn-label: #f8dc95;\n  --dsw-alias-state-warn-secondary: #f2cf7226;\n  --dsw-alias-state-warn-tertiary: #f2cf7214;\n  --dsw-alias-state-error-primary: #ff8d9e;\n  --dsw-alias-state-error-secondary: #ff8d9e26;\n  --dsw-alias-state-business-primary: #8fbcff;\n  --dsw-alias-state-business-tertiary: #8fbcff26;\n  --dsw-alias-state-idle-primary: #7a8a90;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #111a1e;\n  --dsw-alias-settings-card-stroke: #8fd8e82e;\n  --dsw-alias-turn-trigger-bg: #10181c;\n  --dsw-alias-turn-trigger-bg-hover: #172228;\n  --dsw-alias-toast-bg: #162127;\n  --dsw-alias-toast-label: #e3eef2;\n  --dsw-alias-tooltip-bg: #1a262d;\n  --dsw-alias-tooltip-key-bg: #24343c;\n  --dsw-alias-menu-icon: #a5b8bf;\n  --dsw-alias-menu-group-header-fill: #5fd8e80f;\n  --dsw-alias-scrollbar-bg-l1: #8fd8e838;\n  --dsw-alias-scrollbar-hover-l1: #8fd8e85c;\n  --dsw-alias-scrollbar-bg-l2: #8fd8e842;\n  --dsw-alias-scrollbar-hover-l2: #8fd8e866;\n\n  /* Vivid-Ebene */\n  --vv-accent: #5fd8e8;\n  --vv-heading: #a6eef7;\n  --vv-heading-soft: #8acdd6;\n  --vv-strong: #f0fdff;\n  --vv-line: #8fd8e833;\n  --vv-line-soft: #8fd8e824;\n  --vv-link-underline: #86e2f073;\n  --vv-code-bg: #5fd8e80d;\n  --vv-inline-code-bg: #86e6f21f;\n  --vv-inline-code-border: #9cecf738;\n  --vv-inline-code-fg: #cdf6fb;\n  --vv-quote-bg: #5fd8e80d;\n  --vv-table-head: #5fd8e81a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #5fd8e8;\n  --vv-selection: #5fd8e84d;\n  --vv-glow: #4fcfe017;\n  --vv-glow-2: #4f9aff12;\n  --vv-sidebar-fill: #0d1519;\n  --vv-hover: #5fd8e814;\n  --vv-active: #5fd8e824;\n  --vv-tip: #162127;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #f3fafc;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #eaf5f8;\n  --dsw-alias-bg-layer-3: #ddeef2;\n  --dsw-alias-bg-skeleton: #e5f1f5;\n\n  --dsw-alias-border-l1: #0f3a451f;\n  --dsw-alias-border-l2: #0f3a452e;\n  --dsw-alias-border-l3: #0f3a4542;\n  --dsw-alias-border-l4: #0f3a455c;\n\n  --dsw-alias-label-primary: #10222a;\n  --dsw-alias-label-primary-bluish: #0f2630;\n  --dsw-alias-label-secondary: #45606a;\n  --dsw-alias-label-tertiary: #617d87;\n  --dsw-alias-label-caption: #79939c;\n  --dsw-alias-label-dimmed: #95adb5;\n  --dsw-alias-link: #0b7484;\n\n  --dsw-alias-brand-primary: #0e8598;\n  --dsw-alias-brand-text: #0a6474;\n  --dsw-alias-interactive-bg-hover: #0e859814;\n  --dsw-alias-interactive-bg-active: #0e859822;\n  --dsw-alias-interactive-bg-hover-accent: #0e85981f;\n  --dsw-alias-button-primary-fill: #0b7b8c;\n  --dsw-alias-button-primary-hover: #086271;\n  --dsw-alias-button-ghost-active-fill: #0e85981a;\n  --dsw-alias-button-ghost-active-border: #0e859840;\n  --dsw-alias-button-ghost-active-hover: #0e859826;\n\n  --dsw-alias-markdown-code-block: #0e85980d;\n  --dsw-alias-markdown-code-block-banner: #0e85981a;\n  --dsw-alias-markdown-inline-code: #0e859814;\n  --dsw-alias-state-success-primary: #0f7a63;\n  --dsw-alias-state-warn-primary: #a1741a;\n  --dsw-alias-state-error-primary: #c04450;\n  --dsw-alias-state-business-primary: #2f63c9;\n  --dsw-alias-state-idle-primary: #7d9096;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #0f3a451a;\n  --dsw-alias-turn-trigger-bg: #eaf5f8;\n  --dsw-alias-turn-trigger-bg-hover: #dfeff3;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #10222a;\n  --dsw-alias-tooltip-bg: #1a262d;\n  --dsw-alias-tooltip-key-bg: #24343c;\n  --dsw-alias-menu-icon: #45606a;\n  --dsw-alias-menu-group-header-fill: #0e85980a;\n  --dsw-alias-scrollbar-bg-l1: #0f3a4533;\n  --dsw-alias-scrollbar-hover-l1: #0f3a4552;\n  --dsw-alias-scrollbar-bg-l2: #0f3a453d;\n  --dsw-alias-scrollbar-hover-l2: #0f3a455c;\n\n  --vv-accent: #0e8598;\n  --vv-heading: #0a6474;\n  --vv-heading-soft: #1c7383;\n  --vv-strong: #08171a;\n  --vv-line: #0f3a452b;\n  --vv-line-soft: #0f3a451f;\n  --vv-link-underline: #0b748473;\n  --vv-code-bg: #0e85980a;\n  --vv-inline-code-bg: #0e859812;\n  --vv-inline-code-border: #0e85982e;\n  --vv-inline-code-fg: #0a5563;\n  --vv-quote-bg: #0e85980a;\n  --vv-table-head: #0e859814;\n  --vv-table-zebra: #0f3a4508;\n  --vv-marker: #0e8598;\n  --vv-selection: #18a0b438;\n  --vv-glow: #4fd0e01a;\n  --vv-glow-2: #4f9aff12;\n  --vv-sidebar-fill: #eef8fb;\n  --vv-hover: #0b6e7c12;\n  --vv-active: #0b6e7c21;\n  --vv-tip: #e6f3f7;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","aurora":"/* ===== DSH Vivid Theme: Aurora =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: AURORA  —  kuehles Blau/Violett, ruhig und klar\n   Gedacht fuer lange Sessions: weiches Off-White statt Reinweiss,\n   blaue Akzente, damit die Augen nicht \"brennen\".\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #0f1319;\n  --dsw-alias-bg-layer-1: #151a23;\n  --dsw-alias-bg-layer-2: #1a212c;\n  --dsw-alias-bg-layer-3: #222b38;\n  --dsw-alias-bg-overlay: #0b0e13f2;\n  --dsw-alias-bg-mask-1: #0b0e13b3;\n  --dsw-alias-bg-mask-2: #0b0e13d9;\n  --dsw-alias-bg-mask-3: #0b0e13f2;\n  --dsw-alias-bg-skeleton: #1c2431;\n\n  /* Linien */\n  --dsw-alias-border-l1: #87a0cd29;\n  --dsw-alias-border-l2: #87a0cd38;\n  --dsw-alias-border-l3: #87a0cd4d;\n  --dsw-alias-border-l4: #87a0cd6b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #e4e9f3;\n  --dsw-alias-label-primary-bluish: #d6e1f6;\n  --dsw-alias-label-primary-dimmed: #b8c4d9;\n  --dsw-alias-label-secondary: #a8b3c7;\n  --dsw-alias-label-tertiary: #828da1;\n  --dsw-alias-label-caption: #6e7889;\n  --dsw-alias-label-dimmed: #5c6675;\n  --dsw-alias-link: #8fb9ff;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #7ca8ff;\n  --dsw-alias-brand-primary-invert: #0f1319;\n  --dsw-alias-brand-text: #a9c4ff;\n  --dsw-alias-interactive-bg-hover: #7ca8ff14;\n  --dsw-alias-interactive-bg-active: #7ca8ff22;\n  --dsw-alias-interactive-bg-hover-accent: #7ca8ff26;\n  --dsw-alias-button-primary-fill: #6b98f5;\n  --dsw-alias-button-primary-hover: #82aaff;\n  --dsw-alias-button-ghost-active-fill: #7ca8ff1f;\n  --dsw-alias-button-ghost-active-border: #7ca8ff47;\n  --dsw-alias-button-ghost-active-hover: #7ca8ff2e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #7ca8ff12;\n  --dsw-alias-markdown-code-block-banner: #7ca8ff1f;\n  --dsw-alias-markdown-inline-code: #8cb4ff24;\n  --dsw-alias-markdown-citation: #7ca8ff3d;\n  --dsw-alias-markdown-tag: #7ca8ff2b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #4ed2a6;\n  --dsw-alias-state-success-secondary: #4ed2a626;\n  --dsw-alias-state-success-tertiary: #4ed2a614;\n  --dsw-alias-state-warn-primary: #f0b45e;\n  --dsw-alias-state-warn-label: #f5c47c;\n  --dsw-alias-state-warn-secondary: #f0b45e26;\n  --dsw-alias-state-warn-tertiary: #f0b45e14;\n  --dsw-alias-state-error-primary: #f1798a;\n  --dsw-alias-state-error-secondary: #f1798a26;\n  --dsw-alias-state-business-primary: #9aa8ff;\n  --dsw-alias-state-business-tertiary: #9aa8ff26;\n  --dsw-alias-state-idle-primary: #7a8598;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #161c26;\n  --dsw-alias-settings-card-stroke: #87a0cd2e;\n  --dsw-alias-turn-trigger-bg: #151a23;\n  --dsw-alias-turn-trigger-bg-hover: #1d2532;\n  --dsw-alias-toast-bg: #1e2634;\n  --dsw-alias-toast-label: #e4e9f3;\n  --dsw-alias-tooltip-bg: #232c3b;\n  --dsw-alias-tooltip-key-bg: #2c3748;\n  --dsw-alias-menu-icon: #a8b3c7;\n  --dsw-alias-menu-group-header-fill: #7ca8ff0f;\n  --dsw-alias-scrollbar-bg-l1: #87a0cd38;\n  --dsw-alias-scrollbar-hover-l1: #87a0cd5c;\n  --dsw-alias-scrollbar-bg-l2: #87a0cd42;\n  --dsw-alias-scrollbar-hover-l2: #87a0cd66;\n\n  /* Vivid-Ebene */\n  --vv-accent: #7ca8ff;\n  --vv-heading: #c3d6ff;\n  --vv-heading-soft: #a9bede;\n  --vv-strong: #f0f4ff;\n  --vv-line: #87a0cd33;\n  --vv-line-soft: #87a0cd24;\n  --vv-link-underline: #8fb9ff73;\n  --vv-code-bg: #8cafff0e;\n  --vv-inline-code-bg: #8cb4ff21;\n  --vv-inline-code-border: #96beff38;\n  --vv-inline-code-fg: #cfe0ff;\n  --vv-quote-bg: #7ca8ff0f;\n  --vv-table-head: #7ca8ff1a;\n  --vv-table-zebra: #ffffff09;\n  --vv-marker: #7ca8ff;\n  --vv-selection: #7ca8ff4d;\n  --vv-glow: #7ca8ff17;\n  --vv-glow-2: #9678ff12;\n  --vv-sidebar-fill: #121721;\n  --vv-hover: #7ca8ff14;\n  --vv-active: #7ca8ff24;\n  --vv-tip: #1a2230;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #f6f8fc;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #f3f6fb;\n  --dsw-alias-bg-layer-3: #e9eef7;\n  --dsw-alias-bg-skeleton: #e7edf6;\n\n  --dsw-alias-border-l1: #1e3c6e1f;\n  --dsw-alias-border-l2: #1e3c6e2e;\n  --dsw-alias-border-l3: #1e3c6e42;\n  --dsw-alias-border-l4: #1e3c6e5c;\n\n  --dsw-alias-label-primary: #1a2333;\n  --dsw-alias-label-primary-bluish: #1b2c47;\n  --dsw-alias-label-secondary: #4e5c72;\n  --dsw-alias-label-tertiary: #6b7788;\n  --dsw-alias-label-caption: #808b9c;\n  --dsw-alias-label-dimmed: #98a2b1;\n  --dsw-alias-link: #2f6bd8;\n\n  --dsw-alias-brand-primary: #3d78e8;\n  --dsw-alias-brand-text: #2f63c9;\n  --dsw-alias-interactive-bg-hover: #3d78e814;\n  --dsw-alias-interactive-bg-active: #3d78e822;\n  --dsw-alias-interactive-bg-hover-accent: #3d78e81f;\n  --dsw-alias-button-primary-fill: #3d78e8;\n  --dsw-alias-button-primary-hover: #2f63c9;\n  --dsw-alias-button-ghost-active-fill: #3d78e81a;\n  --dsw-alias-button-ghost-active-border: #3d78e840;\n  --dsw-alias-button-ghost-active-hover: #3d78e826;\n\n  --dsw-alias-markdown-code-block: #2d5ab40d;\n  --dsw-alias-markdown-code-block-banner: #2d5ab41a;\n  --dsw-alias-markdown-inline-code: #2d5ab414;\n  --dsw-alias-state-success-primary: #12866a;\n  --dsw-alias-state-warn-primary: #b87514;\n  --dsw-alias-state-error-primary: #cc4455;\n  --dsw-alias-state-business-primary: #3d63d8;\n  --dsw-alias-state-idle-primary: #7a8598;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #1e3c6e1a;\n  --dsw-alias-turn-trigger-bg: #eef3fa;\n  --dsw-alias-turn-trigger-bg-hover: #e6edf9;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #1a2333;\n  --dsw-alias-tooltip-bg: #1f2735;\n  --dsw-alias-tooltip-key-bg: #2c3748;\n  --dsw-alias-menu-icon: #4e5c72;\n  --dsw-alias-menu-group-header-fill: #3d78e80a;\n  --dsw-alias-scrollbar-bg-l1: #1e3c6e33;\n  --dsw-alias-scrollbar-hover-l1: #1e3c6e52;\n  --dsw-alias-scrollbar-bg-l2: #1e3c6e3d;\n  --dsw-alias-scrollbar-hover-l2: #1e3c6e5c;\n\n  --vv-accent: #3d78e8;\n  --vv-heading: #1e5aa8;\n  --vv-heading-soft: #2e5f9e;\n  --vv-strong: #101827;\n  --vv-line: #1e3c6e2b;\n  --vv-line-soft: #1e3c6e1f;\n  --vv-link-underline: #2f6bd873;\n  --vv-code-bg: #2d5ab40a;\n  --vv-inline-code-bg: #2d5ab412;\n  --vv-inline-code-border: #2d5ab42e;\n  --vv-inline-code-fg: #1d3f73;\n  --vv-quote-bg: #2d5ab40a;\n  --vv-table-head: #2d5ab414;\n  --vv-table-zebra: #14326e08;\n  --vv-marker: #3d78e8;\n  --vv-selection: #4678dc38;\n  --vv-glow: #5a8cf01a;\n  --vv-glow-2: #8c6ef012;\n  --vv-sidebar-fill: #eff3fa;\n  --vv-hover: #3c6ec812;\n  --vv-active: #3c6ec821;\n  --vv-tip: #e7edf8;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","crimson":"/* ===== DSH Vivid Theme: Crimson =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: CRIMSON  —  Granatrot auf warmem Dunkelbraun\n   Kuehn statt brav: ein kraeftiger roter Akzent, der trotzdem nicht blendet.\n   Fuer alle, die beim Blick auf die Oberflaeche wach bleiben wollen.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #150b0e;\n  --dsw-alias-bg-layer-1: #1c1014;\n  --dsw-alias-bg-layer-2: #23151a;\n  --dsw-alias-bg-layer-3: #2d1b21;\n  --dsw-alias-bg-overlay: #0f0709f2;\n  --dsw-alias-bg-mask-1: #0f0709b3;\n  --dsw-alias-bg-mask-2: #0f0709d9;\n  --dsw-alias-bg-mask-3: #0f0709f2;\n  --dsw-alias-bg-skeleton: #2a1a20;\n\n  /* Linien */\n  --dsw-alias-border-l1: #f08a9f29;\n  --dsw-alias-border-l2: #f08a9f38;\n  --dsw-alias-border-l3: #f08a9f4d;\n  --dsw-alias-border-l4: #f08a9f6b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #f0e3e7;\n  --dsw-alias-label-primary-bluish: #f7e5ea;\n  --dsw-alias-label-primary-dimmed: #d1bfc4;\n  --dsw-alias-label-secondary: #bda9ae;\n  --dsw-alias-label-tertiary: #968088;\n  --dsw-alias-label-caption: #816b72;\n  --dsw-alias-label-dimmed: #6c585f;\n  --dsw-alias-link: #ff9fb0;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #f2687f;\n  --dsw-alias-brand-primary-invert: #150b0e;\n  --dsw-alias-brand-text: #ffb4c0;\n  --dsw-alias-interactive-bg-hover: #f2687f14;\n  --dsw-alias-interactive-bg-active: #f2687f22;\n  --dsw-alias-interactive-bg-hover-accent: #f2687f26;\n  --dsw-alias-button-primary-fill: #d94a63;\n  --dsw-alias-button-primary-hover: #f2687f;\n  --dsw-alias-button-ghost-active-fill: #f2687f1f;\n  --dsw-alias-button-ghost-active-border: #f2687f47;\n  --dsw-alias-button-ghost-active-hover: #f2687f2e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #f2687f0f;\n  --dsw-alias-markdown-code-block-banner: #f2687f1a;\n  --dsw-alias-markdown-inline-code: #ff8a9c21;\n  --dsw-alias-markdown-citation: #f2687f3d;\n  --dsw-alias-markdown-tag: #f2687f2b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #6fd1a8;\n  --dsw-alias-state-success-secondary: #6fd1a826;\n  --dsw-alias-state-success-tertiary: #6fd1a814;\n  --dsw-alias-state-warn-primary: #f0c06a;\n  --dsw-alias-state-warn-label: #f7d38d;\n  --dsw-alias-state-warn-secondary: #f0c06a26;\n  --dsw-alias-state-warn-tertiary: #f0c06a14;\n  --dsw-alias-state-error-primary: #ff8fa0;\n  --dsw-alias-state-error-secondary: #ff8fa026;\n  --dsw-alias-state-business-primary: #b4a0ff;\n  --dsw-alias-state-business-tertiary: #b4a0ff26;\n  --dsw-alias-state-idle-primary: #8b7a80;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #1e1116;\n  --dsw-alias-settings-card-stroke: #f08a9f2e;\n  --dsw-alias-turn-trigger-bg: #1c1014;\n  --dsw-alias-turn-trigger-bg-hover: #29181e;\n  --dsw-alias-toast-bg: #29181e;\n  --dsw-alias-toast-label: #f0e3e7;\n  --dsw-alias-tooltip-bg: #2f1c22;\n  --dsw-alias-tooltip-key-bg: #3b252c;\n  --dsw-alias-menu-icon: #bda9ae;\n  --dsw-alias-menu-group-header-fill: #f2687f0f;\n  --dsw-alias-scrollbar-bg-l1: #f08a9f38;\n  --dsw-alias-scrollbar-hover-l1: #f08a9f5c;\n  --dsw-alias-scrollbar-bg-l2: #f08a9f42;\n  --dsw-alias-scrollbar-hover-l2: #f08a9f66;\n\n  /* Vivid-Ebene */\n  --vv-accent: #f2687f;\n  --vv-heading: #ffb4c0;\n  --vv-heading-soft: #e6a3ae;\n  --vv-strong: #fff2f4;\n  --vv-line: #f08a9f33;\n  --vv-line-soft: #f08a9f24;\n  --vv-link-underline: #ff9fb073;\n  --vv-code-bg: #f2687f0d;\n  --vv-inline-code-bg: #ff8a9c1f;\n  --vv-inline-code-border: #ffa0b038;\n  --vv-inline-code-fg: #ffd0d9;\n  --vv-quote-bg: #f2687f0d;\n  --vv-table-head: #f2687f1a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #f2687f;\n  --vv-selection: #f2687f4d;\n  --vv-glow: #ff5a7a17;\n  --vv-glow-2: #ff8a4a12;\n  --vv-sidebar-fill: #170d11;\n  --vv-hover: #f2687f14;\n  --vv-active: #f2687f24;\n  --vv-tip: #27161c;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #fdf4f5;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #fbeaec;\n  --dsw-alias-bg-layer-3: #f5dfe2;\n  --dsw-alias-bg-skeleton: #f7e7ea;\n\n  --dsw-alias-border-l1: #5c1a281f;\n  --dsw-alias-border-l2: #5c1a282e;\n  --dsw-alias-border-l3: #5c1a2842;\n  --dsw-alias-border-l4: #5c1a285c;\n\n  --dsw-alias-label-primary: #2a171b;\n  --dsw-alias-label-primary-bluish: #331a21;\n  --dsw-alias-label-secondary: #6b5258;\n  --dsw-alias-label-tertiary: #866d74;\n  --dsw-alias-label-caption: #9a828a;\n  --dsw-alias-label-dimmed: #b3a0a6;\n  --dsw-alias-link: #b02a44;\n\n  --dsw-alias-brand-primary: #cf3852;\n  --dsw-alias-brand-text: #a82438;\n  --dsw-alias-interactive-bg-hover: #cf385214;\n  --dsw-alias-interactive-bg-active: #cf385222;\n  --dsw-alias-interactive-bg-hover-accent: #cf38521f;\n  --dsw-alias-button-primary-fill: #c22f48;\n  --dsw-alias-button-primary-hover: #a82438;\n  --dsw-alias-button-ghost-active-fill: #cf38521a;\n  --dsw-alias-button-ghost-active-border: #cf385240;\n  --dsw-alias-button-ghost-active-hover: #cf385226;\n\n  --dsw-alias-markdown-code-block: #c22f480d;\n  --dsw-alias-markdown-code-block-banner: #c22f481a;\n  --dsw-alias-markdown-inline-code: #c22f4814;\n  --dsw-alias-state-success-primary: #127a5c;\n  --dsw-alias-state-warn-primary: #a86a10;\n  --dsw-alias-state-error-primary: #bf2a3f;\n  --dsw-alias-state-business-primary: #6c4bd8;\n  --dsw-alias-state-idle-primary: #8a7a7e;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #5c1a281a;\n  --dsw-alias-turn-trigger-bg: #fbeaec;\n  --dsw-alias-turn-trigger-bg-hover: #f7dfe3;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #2a171b;\n  --dsw-alias-tooltip-bg: #2f1c22;\n  --dsw-alias-tooltip-key-bg: #3b252c;\n  --dsw-alias-menu-icon: #6b5258;\n  --dsw-alias-menu-group-header-fill: #cf38520a;\n  --dsw-alias-scrollbar-bg-l1: #5c1a2833;\n  --dsw-alias-scrollbar-hover-l1: #5c1a2852;\n  --dsw-alias-scrollbar-bg-l2: #5c1a283d;\n  --dsw-alias-scrollbar-hover-l2: #5c1a285c;\n\n  --vv-accent: #cf3852;\n  --vv-heading: #a3203a;\n  --vv-heading-soft: #a8455c;\n  --vv-strong: #1a0f12;\n  --vv-line: #5c1a282b;\n  --vv-line-soft: #5c1a281f;\n  --vv-link-underline: #b02a4473;\n  --vv-code-bg: #c22f480a;\n  --vv-inline-code-bg: #c22f4812;\n  --vv-inline-code-border: #c22f482e;\n  --vv-inline-code-fg: #7a1a2e;\n  --vv-quote-bg: #c22f480a;\n  --vv-table-head: #c22f4814;\n  --vv-table-zebra: #5c1a2808;\n  --vv-marker: #cf3852;\n  --vv-selection: #dc5a7038;\n  --vv-glow: #ff6a7a1a;\n  --vv-glow-2: #ff9a6a12;\n  --vv-sidebar-fill: #fbeef0;\n  --vv-hover: #8a243812;\n  --vv-active: #8a243821;\n  --vv-tip: #f7e6e9;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","ember":"/* ===== DSH Vivid Theme: Ember =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: EMBER  —  warm, gemuetlich, bernstein- und rosastichig\n   Fuer Abende und Nachtarbeit: weniger Blaulicht, weiche warme Labels.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  --dsw-alias-bg-base: #14100f;\n  --dsw-alias-bg-layer-1: #1a1514;\n  --dsw-alias-bg-layer-2: #211a18;\n  --dsw-alias-bg-layer-3: #2a211e;\n  --dsw-alias-bg-overlay: #100c0bf2;\n  --dsw-alias-bg-mask-1: #100c0bb3;\n  --dsw-alias-bg-mask-2: #100c0bd9;\n  --dsw-alias-bg-mask-3: #100c0bf2;\n  --dsw-alias-bg-skeleton: #241c1a;\n\n  --dsw-alias-border-l1: #ffb48229;\n  --dsw-alias-border-l2: #ffb48238;\n  --dsw-alias-border-l3: #ffb4824d;\n  --dsw-alias-border-l4: #ffb4826b;\n\n  --dsw-alias-label-primary: #ede5e0;\n  --dsw-alias-label-primary-bluish: #f2e6de;\n  --dsw-alias-label-primary-dimmed: #cbbcb3;\n  --dsw-alias-label-secondary: #b6a8a0;\n  --dsw-alias-label-tertiary: #8f817a;\n  --dsw-alias-label-caption: #7b6e67;\n  --dsw-alias-label-dimmed: #675b55;\n  --dsw-alias-link: #ffb98a;\n\n  --dsw-alias-brand-primary: #ffa970;\n  --dsw-alias-brand-primary-invert: #14100f;\n  --dsw-alias-brand-text: #ffc9a6;\n  --dsw-alias-interactive-bg-hover: #ffa97014;\n  --dsw-alias-interactive-bg-active: #ffa97022;\n  --dsw-alias-interactive-bg-hover-accent: #ffa97026;\n  --dsw-alias-button-primary-fill: #e8894b;\n  --dsw-alias-button-primary-hover: #ff9d5e;\n  --dsw-alias-button-ghost-active-fill: #ffa9701f;\n  --dsw-alias-button-ghost-active-border: #ffa97047;\n  --dsw-alias-button-ghost-active-hover: #ffa9702e;\n\n  --dsw-alias-markdown-code-block: #ffaa700f;\n  --dsw-alias-markdown-code-block-banner: #ffaa701a;\n  --dsw-alias-markdown-inline-code: #ffb47821;\n  --dsw-alias-markdown-citation: #ffaa703d;\n  --dsw-alias-markdown-tag: #ffaa702b;\n\n  --dsw-alias-state-success-primary: #7ed3a3;\n  --dsw-alias-state-success-secondary: #7ed3a326;\n  --dsw-alias-state-success-tertiary: #7ed3a314;\n  --dsw-alias-state-warn-primary: #ffc46b;\n  --dsw-alias-state-warn-label: #ffd18d;\n  --dsw-alias-state-warn-secondary: #ffc46b26;\n  --dsw-alias-state-warn-tertiary: #ffc46b14;\n  --dsw-alias-state-error-primary: #ff8e8e;\n  --dsw-alias-state-error-secondary: #ff8e8e26;\n  --dsw-alias-state-business-primary: #c9a2ff;\n  --dsw-alias-state-business-tertiary: #c9a2ff26;\n  --dsw-alias-state-idle-primary: #8e8078;\n\n  --dsw-alias-settings-card-fill: #1b1513;\n  --dsw-alias-settings-card-stroke: #ffb4822e;\n  --dsw-alias-turn-trigger-bg: #1a1514;\n  --dsw-alias-turn-trigger-bg-hover: #261d1a;\n  --dsw-alias-toast-bg: #261d1a;\n  --dsw-alias-toast-label: #ede5e0;\n  --dsw-alias-tooltip-bg: #2b211d;\n  --dsw-alias-tooltip-key-bg: #382b25;\n  --dsw-alias-menu-icon: #b6a8a0;\n  --dsw-alias-menu-group-header-fill: #ffaa700f;\n  --dsw-alias-scrollbar-bg-l1: #ffb48238;\n  --dsw-alias-scrollbar-hover-l1: #ffb4825c;\n  --dsw-alias-scrollbar-bg-l2: #ffb48242;\n  --dsw-alias-scrollbar-hover-l2: #ffb48266;\n\n  --vv-accent: #ffa970;\n  --vv-heading: #ffc9a6;\n  --vv-heading-soft: #e6b394;\n  --vv-strong: #fff3ec;\n  --vv-line: #ffb48233;\n  --vv-line-soft: #ffb48224;\n  --vv-link-underline: #ffb98a73;\n  --vv-code-bg: #ffaa700d;\n  --vv-inline-code-bg: #ffb4781f;\n  --vv-inline-code-border: #ffbe8c38;\n  --vv-inline-code-fg: #ffd9bc;\n  --vv-quote-bg: #ffaa700d;\n  --vv-table-head: #ffaa701a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #ffa970;\n  --vv-selection: #ffaa704d;\n  --vv-glow: #ff965a17;\n  --vv-glow-2: #ff5a7812;\n  --vv-sidebar-fill: #181312;\n  --vv-hover: #ffa97014;\n  --vv-active: #ffa97024;\n  --vv-tip: #241c19;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #fbf7f4;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #f8f1ec;\n  --dsw-alias-bg-layer-3: #f0e6df;\n  --dsw-alias-bg-skeleton: #f2e9e2;\n\n  --dsw-alias-border-l1: #6b432a1f;\n  --dsw-alias-border-l2: #6b432a2e;\n  --dsw-alias-border-l3: #6b432a42;\n  --dsw-alias-border-l4: #6b432a5c;\n\n  --dsw-alias-label-primary: #2a211d;\n  --dsw-alias-label-primary-bluish: #33241c;\n  --dsw-alias-label-secondary: #6b5a51;\n  --dsw-alias-label-tertiary: #857169;\n  --dsw-alias-label-caption: #97837a;\n  --dsw-alias-label-dimmed: #b0a09a;\n  --dsw-alias-link: #b45a16;\n\n  --dsw-alias-brand-primary: #d9772a;\n  --dsw-alias-brand-text: #a9500f;\n  --dsw-alias-interactive-bg-hover: #d9772a14;\n  --dsw-alias-interactive-bg-active: #d9772a22;\n  --dsw-alias-interactive-bg-hover-accent: #d9772a1f;\n  --dsw-alias-button-primary-fill: #c9691f;\n  --dsw-alias-button-primary-hover: #ad5716;\n  --dsw-alias-button-ghost-active-fill: #d9772a1a;\n  --dsw-alias-button-ghost-active-border: #d9772a40;\n  --dsw-alias-button-ghost-active-hover: #d9772a26;\n\n  --dsw-alias-markdown-code-block: #be6e320d;\n  --dsw-alias-markdown-code-block-banner: #be6e321a;\n  --dsw-alias-markdown-inline-code: #be6e3214;\n  --dsw-alias-state-success-primary: #1d7f57;\n  --dsw-alias-state-warn-primary: #a86a10;\n  --dsw-alias-state-error-primary: #c1462f;\n  --dsw-alias-state-business-primary: #8c5ac9;\n  --dsw-alias-state-idle-primary: #8a7a72;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #6b432a1a;\n  --dsw-alias-turn-trigger-bg: #f9f2ec;\n  --dsw-alias-turn-trigger-bg-hover: #f4eae2;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #2a211d;\n  --dsw-alias-tooltip-bg: #2b211d;\n  --dsw-alias-tooltip-key-bg: #382b25;\n  --dsw-alias-menu-icon: #6b5a51;\n  --dsw-alias-menu-group-header-fill: #d9772a0a;\n  --dsw-alias-scrollbar-bg-l1: #6b432a33;\n  --dsw-alias-scrollbar-hover-l1: #6b432a52;\n  --dsw-alias-scrollbar-bg-l2: #6b432a3d;\n  --dsw-alias-scrollbar-hover-l2: #6b432a5c;\n\n  --vv-accent: #d9772a;\n  --vv-heading: #9c4a12;\n  --vv-heading-soft: #a85f2c;\n  --vv-strong: #1f1815;\n  --vv-line: #6b432a2b;\n  --vv-line-soft: #6b432a1f;\n  --vv-link-underline: #b45a1673;\n  --vv-code-bg: #be6e320a;\n  --vv-inline-code-bg: #be6e3212;\n  --vv-inline-code-border: #be6e322e;\n  --vv-inline-code-fg: #7a3e12;\n  --vv-quote-bg: #be6e320a;\n  --vv-table-head: #be6e3214;\n  --vv-table-zebra: #6b432a08;\n  --vv-marker: #d9772a;\n  --vv-selection: #e0823038;\n  --vv-glow: #ff9c5a1a;\n  --vv-glow-2: #ff6a8c12;\n  --vv-sidebar-fill: #f6efe9;\n  --vv-hover: #8a4a1a12;\n  --vv-active: #8a4a1a21;\n  --vv-tip: #f2e8e0;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","iris":"/* ===== DSH Vivid Theme: Iris =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: IRIS  —  satter Violettton, deutlich anders als Aurora-Blau\n   Fuer konzentriertes Arbeiten: klarer Akzent, kuehle neutrale Flaechen,\n   im Hellmodus ein sehr helles Lavendelweiss statt Blaustich.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #121019;\n  --dsw-alias-bg-layer-1: #191623;\n  --dsw-alias-bg-layer-2: #201b2d;\n  --dsw-alias-bg-layer-3: #282139;\n  --dsw-alias-bg-overlay: #0d0b12f2;\n  --dsw-alias-bg-mask-1: #0d0b12b3;\n  --dsw-alias-bg-mask-2: #0d0b12d9;\n  --dsw-alias-bg-mask-3: #0d0b12f2;\n  --dsw-alias-bg-skeleton: #251f33;\n\n  /* Linien */\n  --dsw-alias-border-l1: #b0a0ff29;\n  --dsw-alias-border-l2: #b0a0ff38;\n  --dsw-alias-border-l3: #b0a0ff4d;\n  --dsw-alias-border-l4: #b0a0ff6b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #eae6f5;\n  --dsw-alias-label-primary-bluish: #eee7fb;\n  --dsw-alias-label-primary-dimmed: #c6bedb;\n  --dsw-alias-label-secondary: #aca3c2;\n  --dsw-alias-label-tertiary: #877da0;\n  --dsw-alias-label-caption: #726986;\n  --dsw-alias-label-dimmed: #5e566f;\n  --dsw-alias-link: #b3a2ff;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #a48cff;\n  --dsw-alias-brand-primary-invert: #121019;\n  --dsw-alias-brand-text: #c6b6ff;\n  --dsw-alias-interactive-bg-hover: #a48cff14;\n  --dsw-alias-interactive-bg-active: #a48cff22;\n  --dsw-alias-interactive-bg-hover-accent: #a48cff26;\n  --dsw-alias-button-primary-fill: #8666e6;\n  --dsw-alias-button-primary-hover: #a184ff;\n  --dsw-alias-button-ghost-active-fill: #a48cff1f;\n  --dsw-alias-button-ghost-active-border: #a48cff47;\n  --dsw-alias-button-ghost-active-hover: #a48cff2e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #a48cff0f;\n  --dsw-alias-markdown-code-block-banner: #a48cff1a;\n  --dsw-alias-markdown-inline-code: #b3a0ff21;\n  --dsw-alias-markdown-citation: #a48cff3d;\n  --dsw-alias-markdown-tag: #a48cff2b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #6fd6b0;\n  --dsw-alias-state-success-secondary: #6fd6b026;\n  --dsw-alias-state-success-tertiary: #6fd6b014;\n  --dsw-alias-state-warn-primary: #f2bd6a;\n  --dsw-alias-state-warn-label: #f8ce88;\n  --dsw-alias-state-warn-secondary: #f2bd6a26;\n  --dsw-alias-state-warn-tertiary: #f2bd6a14;\n  --dsw-alias-state-error-primary: #ff8ba0;\n  --dsw-alias-state-error-secondary: #ff8ba026;\n  --dsw-alias-state-business-primary: #7fa8ff;\n  --dsw-alias-state-business-tertiary: #7fa8ff26;\n  --dsw-alias-state-idle-primary: #827a94;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #1a1626;\n  --dsw-alias-settings-card-stroke: #b0a0ff2e;\n  --dsw-alias-turn-trigger-bg: #191623;\n  --dsw-alias-turn-trigger-bg-hover: #221c30;\n  --dsw-alias-toast-bg: #221c30;\n  --dsw-alias-toast-label: #eae6f5;\n  --dsw-alias-tooltip-bg: #29223a;\n  --dsw-alias-tooltip-key-bg: #352c4a;\n  --dsw-alias-menu-icon: #aca3c2;\n  --dsw-alias-menu-group-header-fill: #a48cff0f;\n  --dsw-alias-scrollbar-bg-l1: #b0a0ff38;\n  --dsw-alias-scrollbar-hover-l1: #b0a0ff5c;\n  --dsw-alias-scrollbar-bg-l2: #b0a0ff42;\n  --dsw-alias-scrollbar-hover-l2: #b0a0ff66;\n\n  /* Vivid-Ebene */\n  --vv-accent: #a48cff;\n  --vv-heading: #c9b8ff;\n  --vv-heading-soft: #b0a0e8;\n  --vv-strong: #f5f0ff;\n  --vv-line: #b0a0ff33;\n  --vv-line-soft: #b0a0ff24;\n  --vv-link-underline: #b3a2ff73;\n  --vv-code-bg: #a48cff0d;\n  --vv-inline-code-bg: #b3a0ff1f;\n  --vv-inline-code-border: #c0b0ff38;\n  --vv-inline-code-fg: #ded4ff;\n  --vv-quote-bg: #a48cff0d;\n  --vv-table-head: #a48cff1a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #a48cff;\n  --vv-selection: #a48cff4d;\n  --vv-glow: #8a6cff1a;\n  --vv-glow-2: #ff6ad512;\n  --vv-sidebar-fill: #171320;\n  --vv-hover: #a48cff14;\n  --vv-active: #a48cff24;\n  --vv-tip: #231d31;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #f7f4fd;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #f1ecfb;\n  --dsw-alias-bg-layer-3: #e7dff7;\n  --dsw-alias-bg-skeleton: #ece5f9;\n\n  --dsw-alias-border-l1: #3a2a6b1f;\n  --dsw-alias-border-l2: #3a2a6b2e;\n  --dsw-alias-border-l3: #3a2a6b42;\n  --dsw-alias-border-l4: #3a2a6b5c;\n\n  --dsw-alias-label-primary: #211b33;\n  --dsw-alias-label-primary-bluish: #231b3d;\n  --dsw-alias-label-secondary: #5c5273;\n  --dsw-alias-label-tertiary: #786d8c;\n  --dsw-alias-label-caption: #8a8099;\n  --dsw-alias-label-dimmed: #a49cb2;\n  --dsw-alias-link: #5b3ac4;\n\n  --dsw-alias-brand-primary: #6c4bd8;\n  --dsw-alias-brand-text: #5533b8;\n  --dsw-alias-interactive-bg-hover: #6c4bd814;\n  --dsw-alias-interactive-bg-active: #6c4bd822;\n  --dsw-alias-interactive-bg-hover-accent: #6c4bd81f;\n  --dsw-alias-button-primary-fill: #5f3fca;\n  --dsw-alias-button-primary-hover: #4c2fae;\n  --dsw-alias-button-ghost-active-fill: #6c4bd81a;\n  --dsw-alias-button-ghost-active-border: #6c4bd840;\n  --dsw-alias-button-ghost-active-hover: #6c4bd826;\n\n  --dsw-alias-markdown-code-block: #6c4bd80d;\n  --dsw-alias-markdown-code-block-banner: #6c4bd81a;\n  --dsw-alias-markdown-inline-code: #6c4bd814;\n  --dsw-alias-state-success-primary: #157a63;\n  --dsw-alias-state-warn-primary: #a86a10;\n  --dsw-alias-state-error-primary: #c02f52;\n  --dsw-alias-state-business-primary: #3f61c9;\n  --dsw-alias-state-idle-primary: #8a8296;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #3a2a6b1a;\n  --dsw-alias-turn-trigger-bg: #f3eefc;\n  --dsw-alias-turn-trigger-bg-hover: #ece5f9;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #211b33;\n  --dsw-alias-tooltip-bg: #29223a;\n  --dsw-alias-tooltip-key-bg: #352c4a;\n  --dsw-alias-menu-icon: #5c5273;\n  --dsw-alias-menu-group-header-fill: #6c4bd80a;\n  --dsw-alias-scrollbar-bg-l1: #3a2a6b33;\n  --dsw-alias-scrollbar-hover-l1: #3a2a6b52;\n  --dsw-alias-scrollbar-bg-l2: #3a2a6b3d;\n  --dsw-alias-scrollbar-hover-l2: #3a2a6b5c;\n\n  --vv-accent: #6c4bd8;\n  --vv-heading: #4b2fa8;\n  --vv-heading-soft: #5a43a8;\n  --vv-strong: #171223;\n  --vv-line: #3a2a6b2b;\n  --vv-line-soft: #3a2a6b1f;\n  --vv-link-underline: #5b3ac473;\n  --vv-code-bg: #6c4bd80a;\n  --vv-inline-code-bg: #6c4bd812;\n  --vv-inline-code-border: #6c4bd82e;\n  --vv-inline-code-fg: #3a2478;\n  --vv-quote-bg: #6c4bd80a;\n  --vv-table-head: #6c4bd814;\n  --vv-table-zebra: #3a2a6b08;\n  --vv-marker: #6c4bd8;\n  --vv-selection: #7a5ae038;\n  --vv-glow: #8a6cff1a;\n  --vv-glow-2: #ff6ad512;\n  --vv-sidebar-fill: #f2ecfa;\n  --vv-hover: #4a2f9612;\n  --vv-active: #4a2f9621;\n  --vv-tip: #f0eafa;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","mint":"/* ===== DSH Vivid Theme: Mint =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: MINT  —  ruhiges Teal/Gruen, sehr entspannt fuer die Augen\n   Niedrige Blauanteile, weiche Kontraste, gruene Akzente.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  --dsw-alias-bg-base: #0c1312;\n  --dsw-alias-bg-layer-1: #111a18;\n  --dsw-alias-bg-layer-2: #16211f;\n  --dsw-alias-bg-layer-3: #1d2a27;\n  --dsw-alias-bg-overlay: #081010f2;\n  --dsw-alias-bg-mask-1: #081010b3;\n  --dsw-alias-bg-mask-2: #081010d9;\n  --dsw-alias-bg-mask-3: #081010f2;\n  --dsw-alias-bg-skeleton: #172421;\n\n  --dsw-alias-border-l1: #59d3b429;\n  --dsw-alias-border-l2: #59d3b438;\n  --dsw-alias-border-l3: #59d3b44d;\n  --dsw-alias-border-l4: #59d3b46b;\n\n  --dsw-alias-label-primary: #dfede9;\n  --dsw-alias-label-primary-bluish: #d7ece6;\n  --dsw-alias-label-primary-dimmed: #bdd0cb;\n  --dsw-alias-label-secondary: #a6bab5;\n  --dsw-alias-label-tertiary: #7f938e;\n  --dsw-alias-label-caption: #6b7f7a;\n  --dsw-alias-label-dimmed: #596b67;\n  --dsw-alias-link: #6fe0c0;\n\n  --dsw-alias-brand-primary: #59d3b4;\n  --dsw-alias-brand-primary-invert: #0c1312;\n  --dsw-alias-brand-text: #96e9d4;\n  --dsw-alias-interactive-bg-hover: #59d3b414;\n  --dsw-alias-interactive-bg-active: #59d3b422;\n  --dsw-alias-interactive-bg-hover-accent: #59d3b426;\n  --dsw-alias-button-primary-fill: #3fbf9f;\n  --dsw-alias-button-primary-hover: #56d6b4;\n  --dsw-alias-button-ghost-active-fill: #59d3b41f;\n  --dsw-alias-button-ghost-active-border: #59d3b447;\n  --dsw-alias-button-ghost-active-hover: #59d3b42e;\n\n  --dsw-alias-markdown-code-block: #59d3b40f;\n  --dsw-alias-markdown-code-block-banner: #59d3b41a;\n  --dsw-alias-markdown-inline-code: #59d3b421;\n  --dsw-alias-markdown-citation: #59d3b43d;\n  --dsw-alias-markdown-tag: #59d3b42b;\n\n  --dsw-alias-state-success-primary: #4fd6a9;\n  --dsw-alias-state-success-secondary: #4fd6a926;\n  --dsw-alias-state-success-tertiary: #4fd6a914;\n  --dsw-alias-state-warn-primary: #e9c46a;\n  --dsw-alias-state-warn-label: #f0d48c;\n  --dsw-alias-state-warn-secondary: #e9c46a26;\n  --dsw-alias-state-warn-tertiary: #e9c46a14;\n  --dsw-alias-state-error-primary: #ef8a80;\n  --dsw-alias-state-error-secondary: #ef8a8026;\n  --dsw-alias-state-business-primary: #7fb0ff;\n  --dsw-alias-state-business-tertiary: #7fb0ff26;\n  --dsw-alias-state-idle-primary: #7a8f8a;\n\n  --dsw-alias-settings-card-fill: #121c1a;\n  --dsw-alias-settings-card-stroke: #59d3b42e;\n  --dsw-alias-turn-trigger-bg: #111a18;\n  --dsw-alias-turn-trigger-bg-hover: #19251f;\n  --dsw-alias-toast-bg: #17241f;\n  --dsw-alias-toast-label: #dfede9;\n  --dsw-alias-tooltip-bg: #1c2a26;\n  --dsw-alias-tooltip-key-bg: #27352f;\n  --dsw-alias-menu-icon: #a6bab5;\n  --dsw-alias-menu-group-header-fill: #59d3b40f;\n  --dsw-alias-scrollbar-bg-l1: #59d3b438;\n  --dsw-alias-scrollbar-hover-l1: #59d3b45c;\n  --dsw-alias-scrollbar-bg-l2: #59d3b442;\n  --dsw-alias-scrollbar-hover-l2: #59d3b466;\n\n  --vv-accent: #59d3b4;\n  --vv-heading: #8de8d0;\n  --vv-heading-soft: #7fc7b4;\n  --vv-strong: #f0fffa;\n  --vv-line: #59d3b433;\n  --vv-line-soft: #59d3b424;\n  --vv-link-underline: #6fe0c073;\n  --vv-code-bg: #59d3b40d;\n  --vv-inline-code-bg: #59d3b41f;\n  --vv-inline-code-border: #6fe0c038;\n  --vv-inline-code-fg: #b8f2e4;\n  --vv-quote-bg: #59d3b40d;\n  --vv-table-head: #59d3b41a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #59d3b4;\n  --vv-selection: #59d3b44d;\n  --vv-glow: #59d3b417;\n  --vv-glow-2: #5a9cff12;\n  --vv-sidebar-fill: #0f1716;\n  --vv-hover: #59d3b414;\n  --vv-active: #59d3b424;\n  --vv-tip: #16211f;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #f4faf8;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #edf6f3;\n  --dsw-alias-bg-layer-3: #e3efea;\n  --dsw-alias-bg-skeleton: #e8f2ee;\n\n  --dsw-alias-border-l1: #0f55441f;\n  --dsw-alias-border-l2: #0f55442e;\n  --dsw-alias-border-l3: #0f554442;\n  --dsw-alias-border-l4: #0f55445c;\n\n  --dsw-alias-label-primary: #12211d;\n  --dsw-alias-label-primary-bluish: #142821;\n  --dsw-alias-label-secondary: #4a625c;\n  --dsw-alias-label-tertiary: #6a827c;\n  --dsw-alias-label-caption: #7f968f;\n  --dsw-alias-label-dimmed: #9bb0aa;\n  --dsw-alias-link: #12836a;\n\n  --dsw-alias-brand-primary: #12896c;\n  --dsw-alias-brand-text: #0c6b54;\n  --dsw-alias-interactive-bg-hover: #12896c14;\n  --dsw-alias-interactive-bg-active: #12896c22;\n  --dsw-alias-interactive-bg-hover-accent: #12896c1f;\n  --dsw-alias-button-primary-fill: #12896c;\n  --dsw-alias-button-primary-hover: #0c6b54;\n  --dsw-alias-button-ghost-active-fill: #12896c1a;\n  --dsw-alias-button-ghost-active-border: #12896c40;\n  --dsw-alias-button-ghost-active-hover: #12896c26;\n\n  --dsw-alias-markdown-code-block: #12896c0d;\n  --dsw-alias-markdown-code-block-banner: #12896c1a;\n  --dsw-alias-markdown-inline-code: #12896c14;\n  --dsw-alias-state-success-primary: #0f7a5c;\n  --dsw-alias-state-warn-primary: #a1741a;\n  --dsw-alias-state-error-primary: #c4524a;\n  --dsw-alias-state-business-primary: #2f63c9;\n  --dsw-alias-state-idle-primary: #7d938f;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #0f55441a;\n  --dsw-alias-turn-trigger-bg: #ecf6f2;\n  --dsw-alias-turn-trigger-bg-hover: #e2f0eb;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #12211d;\n  --dsw-alias-tooltip-bg: #16211f;\n  --dsw-alias-tooltip-key-bg: #273530;\n  --dsw-alias-menu-icon: #4a625c;\n  --dsw-alias-menu-group-header-fill: #12896c0a;\n  --dsw-alias-scrollbar-bg-l1: #0f554433;\n  --dsw-alias-scrollbar-hover-l1: #0f554452;\n  --dsw-alias-scrollbar-bg-l2: #0f55443d;\n  --dsw-alias-scrollbar-hover-l2: #0f55445c;\n\n  --vv-accent: #12896c;\n  --vv-heading: #0e7a60;\n  --vv-heading-soft: #2c7d68;\n  --vv-strong: #0a1815;\n  --vv-line: #0f55442b;\n  --vv-line-soft: #0f55441f;\n  --vv-link-underline: #12836a73;\n  --vv-code-bg: #12896c0a;\n  --vv-inline-code-bg: #12896c12;\n  --vv-inline-code-border: #12896c2e;\n  --vv-inline-code-fg: #0c5f4b;\n  --vv-quote-bg: #12896c0a;\n  --vv-table-head: #12896c14;\n  --vv-table-zebra: #0f554408;\n  --vv-marker: #12896c;\n  --vv-selection: #2aa88a38;\n  --vv-glow: #4fd6b01a;\n  --vv-glow-2: #5a9cff12;\n  --vv-sidebar-fill: #eff8f5;\n  --vv-hover: #12896c12;\n  --vv-active: #12896c21;\n  --vv-tip: #e6f3ee;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","moss":"/* ===== DSH Vivid Theme: Moss =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: MOSS  —  Waldgruen und Oliv, gedaempft und natuerlich\n   Fuer sehr lange Sessions: Moosgruene Akzente auf warm-grauem Grund,\n   deutlich ruhiger als Mint (das ins Tuerkis geht).\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #0f140f;\n  --dsw-alias-bg-layer-1: #151b15;\n  --dsw-alias-bg-layer-2: #1b231b;\n  --dsw-alias-bg-layer-3: #232d23;\n  --dsw-alias-bg-overlay: #0a0f0af2;\n  --dsw-alias-bg-mask-1: #0a0f0ab3;\n  --dsw-alias-bg-mask-2: #0a0f0ad9;\n  --dsw-alias-bg-mask-3: #0a0f0af2;\n  --dsw-alias-bg-skeleton: #202a20;\n\n  /* Linien */\n  --dsw-alias-border-l1: #aad48f29;\n  --dsw-alias-border-l2: #aad48f38;\n  --dsw-alias-border-l3: #aad48f4d;\n  --dsw-alias-border-l4: #aad48f6b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #e7ede1;\n  --dsw-alias-label-primary-bluish: #e2eddb;\n  --dsw-alias-label-primary-dimmed: #c2ceba;\n  --dsw-alias-label-secondary: #a9b8a0;\n  --dsw-alias-label-tertiary: #83907a;\n  --dsw-alias-label-caption: #6f7a66;\n  --dsw-alias-label-dimmed: #5b6554;\n  --dsw-alias-link: #bce38c;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #a8d46a;\n  --dsw-alias-brand-primary-invert: #0f140f;\n  --dsw-alias-brand-text: #cfeaa9;\n  --dsw-alias-interactive-bg-hover: #a8d46a14;\n  --dsw-alias-interactive-bg-active: #a8d46a22;\n  --dsw-alias-interactive-bg-hover-accent: #a8d46a26;\n  --dsw-alias-button-primary-fill: #7fae42;\n  --dsw-alias-button-primary-hover: #97c95b;\n  --dsw-alias-button-ghost-active-fill: #a8d46a1f;\n  --dsw-alias-button-ghost-active-border: #a8d46a47;\n  --dsw-alias-button-ghost-active-hover: #a8d46a2e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #a8d46a0f;\n  --dsw-alias-markdown-code-block-banner: #a8d46a1a;\n  --dsw-alias-markdown-inline-code: #b6dd8421;\n  --dsw-alias-markdown-citation: #a8d46a3d;\n  --dsw-alias-markdown-tag: #a8d46a2b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #6ed49c;\n  --dsw-alias-state-success-secondary: #6ed49c26;\n  --dsw-alias-state-success-tertiary: #6ed49c14;\n  --dsw-alias-state-warn-primary: #e7c76b;\n  --dsw-alias-state-warn-label: #f0d78a;\n  --dsw-alias-state-warn-secondary: #e7c76b26;\n  --dsw-alias-state-warn-tertiary: #e7c76b14;\n  --dsw-alias-state-error-primary: #f18a86;\n  --dsw-alias-state-error-secondary: #f18a8626;\n  --dsw-alias-state-business-primary: #93b9ff;\n  --dsw-alias-state-business-tertiary: #93b9ff26;\n  --dsw-alias-state-idle-primary: #7e8a78;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #161d16;\n  --dsw-alias-settings-card-stroke: #aad48f2e;\n  --dsw-alias-turn-trigger-bg: #151b15;\n  --dsw-alias-turn-trigger-bg-hover: #1e271e;\n  --dsw-alias-toast-bg: #1e271e;\n  --dsw-alias-toast-label: #e7ede1;\n  --dsw-alias-tooltip-bg: #242e24;\n  --dsw-alias-tooltip-key-bg: #303a30;\n  --dsw-alias-menu-icon: #a9b8a0;\n  --dsw-alias-menu-group-header-fill: #a8d46a0f;\n  --dsw-alias-scrollbar-bg-l1: #aad48f38;\n  --dsw-alias-scrollbar-hover-l1: #aad48f5c;\n  --dsw-alias-scrollbar-bg-l2: #aad48f42;\n  --dsw-alias-scrollbar-hover-l2: #aad48f66;\n\n  /* Vivid-Ebene */\n  --vv-accent: #a8d46a;\n  --vv-heading: #cbe79f;\n  --vv-heading-soft: #b0cd8f;\n  --vv-strong: #f4fbee;\n  --vv-line: #aad48f33;\n  --vv-line-soft: #aad48f24;\n  --vv-link-underline: #bce38c73;\n  --vv-code-bg: #a8d46a0d;\n  --vv-inline-code-bg: #b6dd841f;\n  --vv-inline-code-border: #c6e79c38;\n  --vv-inline-code-fg: #dcf3c3;\n  --vv-quote-bg: #a8d46a0d;\n  --vv-table-head: #a8d46a1a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #a8d46a;\n  --vv-selection: #a8d46a4d;\n  --vv-glow: #8fbf5a17;\n  --vv-glow-2: #56c9a412;\n  --vv-sidebar-fill: #111711;\n  --vv-hover: #a8d46a14;\n  --vv-active: #a8d46a24;\n  --vv-tip: #1c251c;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #f6faf2;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #eff6e9;\n  --dsw-alias-bg-layer-3: #e4efdb;\n  --dsw-alias-bg-skeleton: #eaf2e3;\n\n  --dsw-alias-border-l1: #2f4a221f;\n  --dsw-alias-border-l2: #2f4a222e;\n  --dsw-alias-border-l3: #2f4a2242;\n  --dsw-alias-border-l4: #2f4a225c;\n\n  --dsw-alias-label-primary: #1a2416;\n  --dsw-alias-label-primary-bluish: #1f2c15;\n  --dsw-alias-label-secondary: #4c5c44;\n  --dsw-alias-label-tertiary: #6a7962;\n  --dsw-alias-label-caption: #7e8c77;\n  --dsw-alias-label-dimmed: #9aa793;\n  --dsw-alias-link: #3f7a1f;\n\n  --dsw-alias-brand-primary: #4d8624;\n  --dsw-alias-brand-text: #3b6b18;\n  --dsw-alias-interactive-bg-hover: #4d862414;\n  --dsw-alias-interactive-bg-active: #4d862422;\n  --dsw-alias-interactive-bg-hover-accent: #4d86241f;\n  --dsw-alias-button-primary-fill: #4a8122;\n  --dsw-alias-button-primary-hover: #3b6b18;\n  --dsw-alias-button-ghost-active-fill: #4d86241a;\n  --dsw-alias-button-ghost-active-border: #4d862440;\n  --dsw-alias-button-ghost-active-hover: #4d862426;\n\n  --dsw-alias-markdown-code-block: #4d86240d;\n  --dsw-alias-markdown-code-block-banner: #4d86241a;\n  --dsw-alias-markdown-inline-code: #4d862414;\n  --dsw-alias-state-success-primary: #157a4a;\n  --dsw-alias-state-warn-primary: #a1741a;\n  --dsw-alias-state-error-primary: #c0524a;\n  --dsw-alias-state-business-primary: #2f63c9;\n  --dsw-alias-state-idle-primary: #7d8c76;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #2f4a221a;\n  --dsw-alias-turn-trigger-bg: #eff6e9;\n  --dsw-alias-turn-trigger-bg-hover: #e6f0dd;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #1a2416;\n  --dsw-alias-tooltip-bg: #242e24;\n  --dsw-alias-tooltip-key-bg: #303a30;\n  --dsw-alias-menu-icon: #4c5c44;\n  --dsw-alias-menu-group-header-fill: #4d86240a;\n  --dsw-alias-scrollbar-bg-l1: #2f4a2233;\n  --dsw-alias-scrollbar-hover-l1: #2f4a2252;\n  --dsw-alias-scrollbar-bg-l2: #2f4a223d;\n  --dsw-alias-scrollbar-hover-l2: #2f4a225c;\n\n  --vv-accent: #4d8624;\n  --vv-heading: #2f6b14;\n  --vv-heading-soft: #406b2c;\n  --vv-strong: #0c1509;\n  --vv-line: #2f4a222b;\n  --vv-line-soft: #2f4a221f;\n  --vv-link-underline: #3f7a1f73;\n  --vv-code-bg: #4d86240a;\n  --vv-inline-code-bg: #4d862412;\n  --vv-inline-code-border: #4d86242e;\n  --vv-inline-code-fg: #2a5a10;\n  --vv-quote-bg: #4d86240a;\n  --vv-table-head: #4d862414;\n  --vv-table-zebra: #2f4a2208;\n  --vv-marker: #4d8624;\n  --vv-selection: #4f9a2a38;\n  --vv-glow: #7fc04a1a;\n  --vv-glow-2: #4fb8a012;\n  --vv-sidebar-fill: #f1f8ec;\n  --vv-hover: #3f6a1f12;\n  --vv-active: #3f6a1f21;\n  --vv-tip: #ebf3e4;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","noir":"/* ===== DSH Vivid Theme: Noir =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: NOIR  —  reines Schwarz und Silber, OLED-freundlich\n   Fast ohne Farbe: Der Akzent ist helles Silber, Zustaende behalten nur\n   einen Hauch Farbe, damit Fehler und Erfolg noch unterscheidbar sind.\n   Im Hellmodus ein neutrales Papierweiss mit Tintenakzent.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #000000;\n  --dsw-alias-bg-layer-1: #08090a;\n  --dsw-alias-bg-layer-2: #0e1011;\n  --dsw-alias-bg-layer-3: #16181a;\n  --dsw-alias-bg-overlay: #000000f2;\n  --dsw-alias-bg-mask-1: #000000b3;\n  --dsw-alias-bg-mask-2: #000000d9;\n  --dsw-alias-bg-mask-3: #000000f2;\n  --dsw-alias-bg-skeleton: #121415;\n\n  /* Linien */\n  --dsw-alias-border-l1: #ffffff29;\n  --dsw-alias-border-l2: #ffffff38;\n  --dsw-alias-border-l3: #ffffff4d;\n  --dsw-alias-border-l4: #ffffff6b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #f2f4f6;\n  --dsw-alias-label-primary-bluish: #eef4fa;\n  --dsw-alias-label-primary-dimmed: #c8ccd0;\n  --dsw-alias-label-secondary: #a6abb0;\n  --dsw-alias-label-tertiary: #81868b;\n  --dsw-alias-label-caption: #6c7176;\n  --dsw-alias-label-dimmed: #595e63;\n  --dsw-alias-link: #cfd8e0;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #e6eaee;\n  --dsw-alias-brand-primary-invert: #000000;\n  --dsw-alias-brand-text: #f5f7f9;\n  --dsw-alias-interactive-bg-hover: #ffffff14;\n  --dsw-alias-interactive-bg-active: #ffffff22;\n  --dsw-alias-interactive-bg-hover-accent: #ffffff26;\n  --dsw-alias-button-primary-fill: #d4dade;\n  --dsw-alias-button-primary-hover: #ffffff;\n  --dsw-alias-button-ghost-active-fill: #ffffff1f;\n  --dsw-alias-button-ghost-active-border: #ffffff4d;\n  --dsw-alias-button-ghost-active-hover: #ffffff2e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #ffffff0a;\n  --dsw-alias-markdown-code-block-banner: #ffffff14;\n  --dsw-alias-markdown-inline-code: #ffffff1f;\n  --dsw-alias-markdown-citation: #ffffff38;\n  --dsw-alias-markdown-tag: #ffffff29;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #74d6a8;\n  --dsw-alias-state-success-secondary: #74d6a826;\n  --dsw-alias-state-success-tertiary: #74d6a814;\n  --dsw-alias-state-warn-primary: #e8c46a;\n  --dsw-alias-state-warn-label: #f2d693;\n  --dsw-alias-state-warn-secondary: #e8c46a26;\n  --dsw-alias-state-warn-tertiary: #e8c46a14;\n  --dsw-alias-state-error-primary: #f28d97;\n  --dsw-alias-state-error-secondary: #f28d9726;\n  --dsw-alias-state-business-primary: #a8b4e8;\n  --dsw-alias-state-business-tertiary: #a8b4e826;\n  --dsw-alias-state-idle-primary: #7d8287;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #0b0c0d;\n  --dsw-alias-settings-card-stroke: #ffffff2e;\n  --dsw-alias-turn-trigger-bg: #08090a;\n  --dsw-alias-turn-trigger-bg-hover: #121415;\n  --dsw-alias-toast-bg: #121415;\n  --dsw-alias-toast-label: #f2f4f6;\n  --dsw-alias-tooltip-bg: #191b1d;\n  --dsw-alias-tooltip-key-bg: #24272a;\n  --dsw-alias-menu-icon: #a6abb0;\n  --dsw-alias-menu-group-header-fill: #ffffff0f;\n  --dsw-alias-scrollbar-bg-l1: #ffffff38;\n  --dsw-alias-scrollbar-hover-l1: #ffffff5c;\n  --dsw-alias-scrollbar-bg-l2: #ffffff42;\n  --dsw-alias-scrollbar-hover-l2: #ffffff66;\n\n  /* Vivid-Ebene */\n  --vv-accent: #e6eaee;\n  --vv-heading: #ffffff;\n  --vv-heading-soft: #c3c9cf;\n  --vv-strong: #ffffff;\n  --vv-line: #ffffff33;\n  --vv-line-soft: #ffffff24;\n  --vv-link-underline: #cfd8e073;\n  --vv-code-bg: #ffffff0a;\n  --vv-inline-code-bg: #ffffff1f;\n  --vv-inline-code-border: #ffffff38;\n  --vv-inline-code-fg: #ffffff;\n  --vv-quote-bg: #ffffff0a;\n  --vv-table-head: #ffffff14;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #ffffff;\n  --vv-selection: #ffffff4d;\n  --vv-glow: #ffffff10;\n  --vv-glow-2: #c8d4e00c;\n  --vv-sidebar-fill: #050505;\n  --vv-hover: #ffffff14;\n  --vv-active: #ffffff24;\n  --vv-tip: #141617;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #f7f8f9;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #f0f2f3;\n  --dsw-alias-bg-layer-3: #e6e9eb;\n  --dsw-alias-bg-skeleton: #eceff0;\n\n  --dsw-alias-border-l1: #14181c1f;\n  --dsw-alias-border-l2: #14181c2e;\n  --dsw-alias-border-l3: #14181c42;\n  --dsw-alias-border-l4: #14181c5c;\n\n  --dsw-alias-label-primary: #121517;\n  --dsw-alias-label-primary-bluish: #111a22;\n  --dsw-alias-label-secondary: #4f565c;\n  --dsw-alias-label-tertiary: #6b7278;\n  --dsw-alias-label-caption: #7f858b;\n  --dsw-alias-label-dimmed: #9aa0a6;\n  --dsw-alias-link: #2b3f52;\n\n  --dsw-alias-brand-primary: #1f2933;\n  --dsw-alias-brand-text: #121a22;\n  --dsw-alias-interactive-bg-hover: #1f293314;\n  --dsw-alias-interactive-bg-active: #1f293322;\n  --dsw-alias-interactive-bg-hover-accent: #1f29331f;\n  --dsw-alias-button-primary-fill: #202a33;\n  --dsw-alias-button-primary-hover: #121a22;\n  --dsw-alias-button-ghost-active-fill: #1f29331a;\n  --dsw-alias-button-ghost-active-border: #1f293340;\n  --dsw-alias-button-ghost-active-hover: #1f293326;\n\n  --dsw-alias-markdown-code-block: #1f29330d;\n  --dsw-alias-markdown-code-block-banner: #1f29331a;\n  --dsw-alias-markdown-inline-code: #1f293314;\n  --dsw-alias-state-success-primary: #157a63;\n  --dsw-alias-state-warn-primary: #96660f;\n  --dsw-alias-state-error-primary: #b83b4b;\n  --dsw-alias-state-business-primary: #45557e;\n  --dsw-alias-state-idle-primary: #7f858b;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #14181c1a;\n  --dsw-alias-turn-trigger-bg: #f0f2f3;\n  --dsw-alias-turn-trigger-bg-hover: #e9ecee;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #121517;\n  --dsw-alias-tooltip-bg: #191b1d;\n  --dsw-alias-tooltip-key-bg: #24272a;\n  --dsw-alias-menu-icon: #4f565c;\n  --dsw-alias-menu-group-header-fill: #1f29330a;\n  --dsw-alias-scrollbar-bg-l1: #14181c33;\n  --dsw-alias-scrollbar-hover-l1: #14181c52;\n  --dsw-alias-scrollbar-bg-l2: #14181c3d;\n  --dsw-alias-scrollbar-hover-l2: #14181c5c;\n\n  --vv-accent: #1f2933;\n  --vv-heading: #121a22;\n  --vv-heading-soft: #3a4753;\n  --vv-strong: #0a0c0e;\n  --vv-line: #14181c2b;\n  --vv-line-soft: #14181c1f;\n  --vv-link-underline: #2b3f5273;\n  --vv-code-bg: #1f29330a;\n  --vv-inline-code-bg: #1f293312;\n  --vv-inline-code-border: #1f29332e;\n  --vv-inline-code-fg: #1a232b;\n  --vv-quote-bg: #1f29330a;\n  --vv-table-head: #1f293314;\n  --vv-table-zebra: #14181c08;\n  --vv-marker: #1f2933;\n  --vv-selection: #1f293338;\n  --vv-glow: #9aa8b41a;\n  --vv-glow-2: #b4bcc41a;\n  --vv-sidebar-fill: #f1f3f4;\n  --vv-hover: #1f293312;\n  --vv-active: #1f293321;\n  --vv-tip: #eef0f2;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","sakura":"/* ===== DSH Vivid Theme: Sakura =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: SAKURA  —  zartes Rosa auf dunklem Pflaumen-Grund\n   Fuer ruhige Abende: warme Rosé-Akzente, weiche Kontraste, kein grelles\n   Weiss. Im Hellmodus ein sehr weiches Altrosa statt Reinweiss.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #161114;\n  --dsw-alias-bg-layer-1: #1d161a;\n  --dsw-alias-bg-layer-2: #241b21;\n  --dsw-alias-bg-layer-3: #2d2229;\n  --dsw-alias-bg-overlay: #110c0ff2;\n  --dsw-alias-bg-mask-1: #110c0fb3;\n  --dsw-alias-bg-mask-2: #110c0fd9;\n  --dsw-alias-bg-mask-3: #110c0ff2;\n  --dsw-alias-bg-skeleton: #2a1f26;\n\n  /* Linien */\n  --dsw-alias-border-l1: #ffa8c829;\n  --dsw-alias-border-l2: #ffa8c838;\n  --dsw-alias-border-l3: #ffa8c84d;\n  --dsw-alias-border-l4: #ffa8c86b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #f2e7ec;\n  --dsw-alias-label-primary-bluish: #f7e9f0;\n  --dsw-alias-label-primary-dimmed: #d3c0c9;\n  --dsw-alias-label-secondary: #bda9b4;\n  --dsw-alias-label-tertiary: #967f8b;\n  --dsw-alias-label-caption: #816b76;\n  --dsw-alias-label-dimmed: #6c5762;\n  --dsw-alias-link: #ffa9c9;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #ff9ec6;\n  --dsw-alias-brand-primary-invert: #161114;\n  --dsw-alias-brand-text: #ffc4da;\n  --dsw-alias-interactive-bg-hover: #ff9ec614;\n  --dsw-alias-interactive-bg-active: #ff9ec622;\n  --dsw-alias-interactive-bg-hover-accent: #ff9ec626;\n  --dsw-alias-button-primary-fill: #e0709f;\n  --dsw-alias-button-primary-hover: #ff92bd;\n  --dsw-alias-button-ghost-active-fill: #ff9ec61f;\n  --dsw-alias-button-ghost-active-border: #ff9ec647;\n  --dsw-alias-button-ghost-active-hover: #ff9ec62e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #ffa0c80f;\n  --dsw-alias-markdown-code-block-banner: #ffa0c81a;\n  --dsw-alias-markdown-inline-code: #ffb0d021;\n  --dsw-alias-markdown-citation: #ffa0c83d;\n  --dsw-alias-markdown-tag: #ffa0c82b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #7fd6b4;\n  --dsw-alias-state-success-secondary: #7fd6b426;\n  --dsw-alias-state-success-tertiary: #7fd6b414;\n  --dsw-alias-state-warn-primary: #f5c06a;\n  --dsw-alias-state-warn-label: #ffd28d;\n  --dsw-alias-state-warn-secondary: #f5c06a26;\n  --dsw-alias-state-warn-tertiary: #f5c06a14;\n  --dsw-alias-state-error-primary: #ff8fa8;\n  --dsw-alias-state-error-secondary: #ff8fa826;\n  --dsw-alias-state-business-primary: #b79cff;\n  --dsw-alias-state-business-tertiary: #b79cff26;\n  --dsw-alias-state-idle-primary: #8e7f89;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #1e171b;\n  --dsw-alias-settings-card-stroke: #ffa8c82e;\n  --dsw-alias-turn-trigger-bg: #1d161a;\n  --dsw-alias-turn-trigger-bg-hover: #271e24;\n  --dsw-alias-toast-bg: #271e24;\n  --dsw-alias-toast-label: #f2e7ec;\n  --dsw-alias-tooltip-bg: #2d222a;\n  --dsw-alias-tooltip-key-bg: #3a2c36;\n  --dsw-alias-menu-icon: #bda9b4;\n  --dsw-alias-menu-group-header-fill: #ffa0c80f;\n  --dsw-alias-scrollbar-bg-l1: #ffa8c838;\n  --dsw-alias-scrollbar-hover-l1: #ffa8c85c;\n  --dsw-alias-scrollbar-bg-l2: #ffa8c842;\n  --dsw-alias-scrollbar-hover-l2: #ffa8c866;\n\n  /* Vivid-Ebene */\n  --vv-accent: #ff9ec6;\n  --vv-heading: #ffc4da;\n  --vv-heading-soft: #e7b3c7;\n  --vv-strong: #fff4f8;\n  --vv-line: #ffa8c833;\n  --vv-line-soft: #ffa8c824;\n  --vv-link-underline: #ffa9c973;\n  --vv-code-bg: #ffa0c80d;\n  --vv-inline-code-bg: #ffb0d01f;\n  --vv-inline-code-border: #ffbcd638;\n  --vv-inline-code-fg: #ffd6e5;\n  --vv-quote-bg: #ffa0c80d;\n  --vv-table-head: #ffa0c81a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #ff9ec6;\n  --vv-selection: #ffa0c84d;\n  --vv-glow: #ff86b417;\n  --vv-glow-2: #b47aff12;\n  --vv-sidebar-fill: #1a1317;\n  --vv-hover: #ff9ec614;\n  --vv-active: #ff9ec624;\n  --vv-tip: #261d23;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #fdf6f9;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #faeef4;\n  --dsw-alias-bg-layer-3: #f4e2ec;\n  --dsw-alias-bg-skeleton: #f5e8ef;\n\n  --dsw-alias-border-l1: #6b2a451f;\n  --dsw-alias-border-l2: #6b2a452e;\n  --dsw-alias-border-l3: #6b2a4542;\n  --dsw-alias-border-l4: #6b2a455c;\n\n  --dsw-alias-label-primary: #2b1f26;\n  --dsw-alias-label-primary-bluish: #331f2a;\n  --dsw-alias-label-secondary: #6d5a64;\n  --dsw-alias-label-tertiary: #87707c;\n  --dsw-alias-label-caption: #9a838e;\n  --dsw-alias-label-dimmed: #b3a1aa;\n  --dsw-alias-link: #b53a6f;\n\n  --dsw-alias-brand-primary: #d4548f;\n  --dsw-alias-brand-text: #a8356a;\n  --dsw-alias-interactive-bg-hover: #d4548f14;\n  --dsw-alias-interactive-bg-active: #d4548f22;\n  --dsw-alias-interactive-bg-hover-accent: #d4548f1f;\n  --dsw-alias-button-primary-fill: #c44a82;\n  --dsw-alias-button-primary-hover: #a8356a;\n  --dsw-alias-button-ghost-active-fill: #d4548f1a;\n  --dsw-alias-button-ghost-active-border: #d4548f40;\n  --dsw-alias-button-ghost-active-hover: #d4548f26;\n\n  --dsw-alias-markdown-code-block: #c4548f0d;\n  --dsw-alias-markdown-code-block-banner: #c4548f1a;\n  --dsw-alias-markdown-inline-code: #c4548f14;\n  --dsw-alias-state-success-primary: #157a5c;\n  --dsw-alias-state-warn-primary: #a86a10;\n  --dsw-alias-state-error-primary: #c02f52;\n  --dsw-alias-state-business-primary: #7c58c9;\n  --dsw-alias-state-idle-primary: #8a7a82;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #6b2a451a;\n  --dsw-alias-turn-trigger-bg: #fbf0f5;\n  --dsw-alias-turn-trigger-bg-hover: #f7e6ef;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #2b1f26;\n  --dsw-alias-tooltip-bg: #2d2229;\n  --dsw-alias-tooltip-key-bg: #3a2c36;\n  --dsw-alias-menu-icon: #6d5a64;\n  --dsw-alias-menu-group-header-fill: #d4548f0a;\n  --dsw-alias-scrollbar-bg-l1: #6b2a4533;\n  --dsw-alias-scrollbar-hover-l1: #6b2a4552;\n  --dsw-alias-scrollbar-bg-l2: #6b2a453d;\n  --dsw-alias-scrollbar-hover-l2: #6b2a455c;\n\n  --vv-accent: #d4548f;\n  --vv-heading: #a8356a;\n  --vv-heading-soft: #a8557f;\n  --vv-strong: #1f161b;\n  --vv-line: #6b2a452b;\n  --vv-line-soft: #6b2a451f;\n  --vv-link-underline: #b53a6f73;\n  --vv-code-bg: #c4548f0a;\n  --vv-inline-code-bg: #c4548f12;\n  --vv-inline-code-border: #c4548f2e;\n  --vv-inline-code-fg: #7a2450;\n  --vv-quote-bg: #c4548f0a;\n  --vv-table-head: #c4548f14;\n  --vv-table-zebra: #6b2a4508;\n  --vv-marker: #d4548f;\n  --vv-selection: #dc5f9638;\n  --vv-glow: #ff8ab81a;\n  --vv-glow-2: #b47aff12;\n  --vv-sidebar-fill: #f8eef3;\n  --vv-hover: #8a2c5612;\n  --vv-active: #8a2c5621;\n  --vv-tip: #f4e7ee;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","sand":"/* ===== DSH Vivid Theme: Sand =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: SAND  —  Pergament und Lehm, warm und fast unbunt\n   Die entspannte Variante fuer Tageslicht: beige Flaechen, ein gedaempfter\n   Ocker-Akzent, keinerlei Blaustich. Im Hellmodus fast wie Papier.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #14120e;\n  --dsw-alias-bg-layer-1: #1a1712;\n  --dsw-alias-bg-layer-2: #211d17;\n  --dsw-alias-bg-layer-3: #2a251d;\n  --dsw-alias-bg-overlay: #0f0d09f2;\n  --dsw-alias-bg-mask-1: #0f0d09b3;\n  --dsw-alias-bg-mask-2: #0f0d09d9;\n  --dsw-alias-bg-mask-3: #0f0d09f2;\n  --dsw-alias-bg-skeleton: #27221a;\n\n  /* Linien */\n  --dsw-alias-border-l1: #d7bd8f29;\n  --dsw-alias-border-l2: #d7bd8f38;\n  --dsw-alias-border-l3: #d7bd8f4d;\n  --dsw-alias-border-l4: #d7bd8f6b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #ece5d8;\n  --dsw-alias-label-primary-bluish: #f0e8da;\n  --dsw-alias-label-primary-dimmed: #cdc2ac;\n  --dsw-alias-label-secondary: #b4a993;\n  --dsw-alias-label-tertiary: #8d8271;\n  --dsw-alias-label-caption: #786e5e;\n  --dsw-alias-label-dimmed: #645b4d;\n  --dsw-alias-link: #e8c48a;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #d3a86a;\n  --dsw-alias-brand-primary-invert: #14120e;\n  --dsw-alias-brand-text: #e8cda0;\n  --dsw-alias-interactive-bg-hover: #d3a86a14;\n  --dsw-alias-interactive-bg-active: #d3a86a22;\n  --dsw-alias-interactive-bg-hover-accent: #d3a86a26;\n  --dsw-alias-button-primary-fill: #b8894a;\n  --dsw-alias-button-primary-hover: #d3a86a;\n  --dsw-alias-button-ghost-active-fill: #d3a86a1f;\n  --dsw-alias-button-ghost-active-border: #d3a86a47;\n  --dsw-alias-button-ghost-active-hover: #d3a86a2e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #d3a86a0f;\n  --dsw-alias-markdown-code-block-banner: #d3a86a1a;\n  --dsw-alias-markdown-inline-code: #e2bd8321;\n  --dsw-alias-markdown-citation: #d3a86a3d;\n  --dsw-alias-markdown-tag: #d3a86a2b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #86cf9e;\n  --dsw-alias-state-success-secondary: #86cf9e26;\n  --dsw-alias-state-success-tertiary: #86cf9e14;\n  --dsw-alias-state-warn-primary: #f0bf6a;\n  --dsw-alias-state-warn-label: #f7d193;\n  --dsw-alias-state-warn-secondary: #f0bf6a26;\n  --dsw-alias-state-warn-tertiary: #f0bf6a14;\n  --dsw-alias-state-error-primary: #ef8f83;\n  --dsw-alias-state-error-secondary: #ef8f8326;\n  --dsw-alias-state-business-primary: #9daee6;\n  --dsw-alias-state-business-tertiary: #9daee626;\n  --dsw-alias-state-idle-primary: #887f70;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #1b1813;\n  --dsw-alias-settings-card-stroke: #d7bd8f2e;\n  --dsw-alias-turn-trigger-bg: #1a1712;\n  --dsw-alias-turn-trigger-bg-hover: #241f18;\n  --dsw-alias-toast-bg: #241f18;\n  --dsw-alias-toast-label: #ece5d8;\n  --dsw-alias-tooltip-bg: #2a251e;\n  --dsw-alias-tooltip-key-bg: #373026;\n  --dsw-alias-menu-icon: #b4a993;\n  --dsw-alias-menu-group-header-fill: #d3a86a0f;\n  --dsw-alias-scrollbar-bg-l1: #d7bd8f38;\n  --dsw-alias-scrollbar-hover-l1: #d7bd8f5c;\n  --dsw-alias-scrollbar-bg-l2: #d7bd8f42;\n  --dsw-alias-scrollbar-hover-l2: #d7bd8f66;\n\n  /* Vivid-Ebene */\n  --vv-accent: #d3a86a;\n  --vv-heading: #ecd3a6;\n  --vv-heading-soft: #c9b391;\n  --vv-strong: #fdf8ef;\n  --vv-line: #d7bd8f33;\n  --vv-line-soft: #d7bd8f24;\n  --vv-link-underline: #e8c48a73;\n  --vv-code-bg: #d3a86a0d;\n  --vv-inline-code-bg: #e2bd831f;\n  --vv-inline-code-border: #e8c89838;\n  --vv-inline-code-fg: #f2e0c4;\n  --vv-quote-bg: #d3a86a0d;\n  --vv-table-head: #d3a86a1a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #d3a86a;\n  --vv-selection: #d3a86a4d;\n  --vv-glow: #e0b57017;\n  --vv-glow-2: #c98a5a12;\n  --vv-sidebar-fill: #16130f;\n  --vv-hover: #d3a86a14;\n  --vv-active: #d3a86a24;\n  --vv-tip: #241f19;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #faf6ee;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #f4eee2;\n  --dsw-alias-bg-layer-3: #ece3d2;\n  --dsw-alias-bg-skeleton: #f0e9da;\n\n  --dsw-alias-border-l1: #4a3a201f;\n  --dsw-alias-border-l2: #4a3a202e;\n  --dsw-alias-border-l3: #4a3a2042;\n  --dsw-alias-border-l4: #4a3a205c;\n\n  --dsw-alias-label-primary: #241f18;\n  --dsw-alias-label-primary-bluish: #2b2419;\n  --dsw-alias-label-secondary: #5f5445;\n  --dsw-alias-label-tertiary: #7a6e5d;\n  --dsw-alias-label-caption: #8f8372;\n  --dsw-alias-label-dimmed: #a89c88;\n  --dsw-alias-link: #8a5a1f;\n\n  --dsw-alias-brand-primary: #9a6a26;\n  --dsw-alias-brand-text: #7d5318;\n  --dsw-alias-interactive-bg-hover: #9a6a2614;\n  --dsw-alias-interactive-bg-active: #9a6a2622;\n  --dsw-alias-interactive-bg-hover-accent: #9a6a261f;\n  --dsw-alias-button-primary-fill: #8d5f20;\n  --dsw-alias-button-primary-hover: #7d5318;\n  --dsw-alias-button-ghost-active-fill: #9a6a261a;\n  --dsw-alias-button-ghost-active-border: #9a6a2640;\n  --dsw-alias-button-ghost-active-hover: #9a6a2626;\n\n  --dsw-alias-markdown-code-block: #8d5f200d;\n  --dsw-alias-markdown-code-block-banner: #8d5f201a;\n  --dsw-alias-markdown-inline-code: #8d5f2014;\n  --dsw-alias-state-success-primary: #157a5c;\n  --dsw-alias-state-warn-primary: #96660f;\n  --dsw-alias-state-error-primary: #bf4a3a;\n  --dsw-alias-state-business-primary: #4a63a0;\n  --dsw-alias-state-idle-primary: #8a8071;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #4a3a201a;\n  --dsw-alias-turn-trigger-bg: #f4eee2;\n  --dsw-alias-turn-trigger-bg-hover: #eee5d4;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #241f18;\n  --dsw-alias-tooltip-bg: #2a251e;\n  --dsw-alias-tooltip-key-bg: #373026;\n  --dsw-alias-menu-icon: #5f5445;\n  --dsw-alias-menu-group-header-fill: #9a6a260a;\n  --dsw-alias-scrollbar-bg-l1: #4a3a2033;\n  --dsw-alias-scrollbar-hover-l1: #4a3a2052;\n  --dsw-alias-scrollbar-bg-l2: #4a3a203d;\n  --dsw-alias-scrollbar-hover-l2: #4a3a205c;\n\n  --vv-accent: #9a6a26;\n  --vv-heading: #7d5318;\n  --vv-heading-soft: #86663c;\n  --vv-strong: #14110c;\n  --vv-line: #4a3a202b;\n  --vv-line-soft: #4a3a201f;\n  --vv-link-underline: #8a5a1f73;\n  --vv-code-bg: #8d5f200a;\n  --vv-inline-code-bg: #8d5f2012;\n  --vv-inline-code-border: #8d5f202e;\n  --vv-inline-code-fg: #6a4210;\n  --vv-quote-bg: #8d5f200a;\n  --vv-table-head: #8d5f2014;\n  --vv-table-zebra: #4a3a2008;\n  --vv-marker: #9a6a26;\n  --vv-selection: #b07f3821;\n  --vv-glow: #e0b5701a;\n  --vv-glow-2: #d79a6a12;\n  --vv-sidebar-fill: #f6efe2;\n  --vv-hover: #7d531812;\n  --vv-active: #7d531821;\n  --vv-tip: #f2ebdc;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","slate":"/* ===== DSH Vivid Theme: Slate =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: SLATE  —  Graphit und Stahl, fast monochrom\n   Fuer alle, die Farbe nur als Orientierung wollen: Flaechen bleiben\n   neutral, Akzente sind ein kuehles Stahlblau. Sehr geringe Buntheit,\n   hohe Lesbarkeit bei langen Texten.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #101214;\n  --dsw-alias-bg-layer-1: #16181b;\n  --dsw-alias-bg-layer-2: #1c1f23;\n  --dsw-alias-bg-layer-3: #24282d;\n  --dsw-alias-bg-overlay: #0b0d0ef2;\n  --dsw-alias-bg-mask-1: #0b0d0eb3;\n  --dsw-alias-bg-mask-2: #0b0d0ed9;\n  --dsw-alias-bg-mask-3: #0b0d0ef2;\n  --dsw-alias-bg-skeleton: #1f2327;\n\n  /* Linien */\n  --dsw-alias-border-l1: #b8c4d029;\n  --dsw-alias-border-l2: #b8c4d038;\n  --dsw-alias-border-l3: #b8c4d04d;\n  --dsw-alias-border-l4: #b8c4d06b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #e6e9ed;\n  --dsw-alias-label-primary-bluish: #e4ebf2;\n  --dsw-alias-label-primary-dimmed: #c2c8cf;\n  --dsw-alias-label-secondary: #a4acb4;\n  --dsw-alias-label-tertiary: #7f878f;\n  --dsw-alias-label-caption: #6b737b;\n  --dsw-alias-label-dimmed: #596066;\n  --dsw-alias-link: #9fc0dd;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #8fb0c9;\n  --dsw-alias-brand-primary-invert: #101214;\n  --dsw-alias-brand-text: #c2d6e6;\n  --dsw-alias-interactive-bg-hover: #8fb0c914;\n  --dsw-alias-interactive-bg-active: #8fb0c922;\n  --dsw-alias-interactive-bg-hover-accent: #8fb0c926;\n  --dsw-alias-button-primary-fill: #7d9db5;\n  --dsw-alias-button-primary-hover: #92b2c9;\n  --dsw-alias-button-ghost-active-fill: #8fb0c91f;\n  --dsw-alias-button-ghost-active-border: #8fb0c947;\n  --dsw-alias-button-ghost-active-hover: #8fb0c92e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #8fb0c90f;\n  --dsw-alias-markdown-code-block-banner: #8fb0c91a;\n  --dsw-alias-markdown-inline-code: #a8c4dc21;\n  --dsw-alias-markdown-citation: #8fb0c93d;\n  --dsw-alias-markdown-tag: #8fb0c92b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #74c9a3;\n  --dsw-alias-state-success-secondary: #74c9a326;\n  --dsw-alias-state-success-tertiary: #74c9a314;\n  --dsw-alias-state-warn-primary: #e3b96d;\n  --dsw-alias-state-warn-label: #efc987;\n  --dsw-alias-state-warn-secondary: #e3b96d26;\n  --dsw-alias-state-warn-tertiary: #e3b96d14;\n  --dsw-alias-state-error-primary: #f08c9b;\n  --dsw-alias-state-error-secondary: #f08c9b26;\n  --dsw-alias-state-business-primary: #93a7e0;\n  --dsw-alias-state-business-tertiary: #93a7e026;\n  --dsw-alias-state-idle-primary: #7d858d;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #17191d;\n  --dsw-alias-settings-card-stroke: #b8c4d02e;\n  --dsw-alias-turn-trigger-bg: #16181b;\n  --dsw-alias-turn-trigger-bg-hover: #1f2327;\n  --dsw-alias-toast-bg: #1f2327;\n  --dsw-alias-toast-label: #e6e9ed;\n  --dsw-alias-tooltip-bg: #23272c;\n  --dsw-alias-tooltip-key-bg: #2d3238;\n  --dsw-alias-menu-icon: #a4acb4;\n  --dsw-alias-menu-group-header-fill: #8fb0c90f;\n  --dsw-alias-scrollbar-bg-l1: #b8c4d038;\n  --dsw-alias-scrollbar-hover-l1: #b8c4d05c;\n  --dsw-alias-scrollbar-bg-l2: #b8c4d042;\n  --dsw-alias-scrollbar-hover-l2: #b8c4d066;\n\n  /* Vivid-Ebene */\n  --vv-accent: #9fbdd6;\n  --vv-heading: #cfdeea;\n  --vv-heading-soft: #b2c4d3;\n  --vv-strong: #f4f7fa;\n  --vv-line: #b8c4d033;\n  --vv-line-soft: #b8c4d024;\n  --vv-link-underline: #9fc0dd73;\n  --vv-code-bg: #8fb0c90d;\n  --vv-inline-code-bg: #a8c4dc1f;\n  --vv-inline-code-border: #b4cade38;\n  --vv-inline-code-fg: #dfebf5;\n  --vv-quote-bg: #8fb0c90d;\n  --vv-table-head: #8fb0c91a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #9fbdd6;\n  --vv-selection: #9fbdd64d;\n  --vv-glow: #7fa6c01a;\n  --vv-glow-2: #7f8fb012;\n  --vv-sidebar-fill: #131619;\n  --vv-hover: #9fbdd614;\n  --vv-active: #9fbdd624;\n  --vv-tip: #1f2429;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #f5f7f8;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #eef1f3;\n  --dsw-alias-bg-layer-3: #e5e9ec;\n  --dsw-alias-bg-skeleton: #e9edef;\n\n  --dsw-alias-border-l1: #24313b1f;\n  --dsw-alias-border-l2: #24313b2e;\n  --dsw-alias-border-l3: #24313b42;\n  --dsw-alias-border-l4: #24313b5c;\n\n  --dsw-alias-label-primary: #1b2126;\n  --dsw-alias-label-primary-bluish: #182430;\n  --dsw-alias-label-secondary: #56626b;\n  --dsw-alias-label-tertiary: #6f7b84;\n  --dsw-alias-label-caption: #828c94;\n  --dsw-alias-label-dimmed: #9ba5ac;\n  --dsw-alias-link: #37607f;\n\n  --dsw-alias-brand-primary: #4a6b8a;\n  --dsw-alias-brand-text: #38566f;\n  --dsw-alias-interactive-bg-hover: #4a6b8a14;\n  --dsw-alias-interactive-bg-active: #4a6b8a22;\n  --dsw-alias-interactive-bg-hover-accent: #4a6b8a1f;\n  --dsw-alias-button-primary-fill: #43607c;\n  --dsw-alias-button-primary-hover: #36506a;\n  --dsw-alias-button-ghost-active-fill: #4a6b8a1a;\n  --dsw-alias-button-ghost-active-border: #4a6b8a40;\n  --dsw-alias-button-ghost-active-hover: #4a6b8a26;\n\n  --dsw-alias-markdown-code-block: #3f64850d;\n  --dsw-alias-markdown-code-block-banner: #3f64851a;\n  --dsw-alias-markdown-inline-code: #3f648514;\n  --dsw-alias-state-success-primary: #157a63;\n  --dsw-alias-state-warn-primary: #96660f;\n  --dsw-alias-state-error-primary: #b83b4b;\n  --dsw-alias-state-business-primary: #4a63a0;\n  --dsw-alias-state-idle-primary: #7f888f;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #24313b1a;\n  --dsw-alias-turn-trigger-bg: #f0f3f5;\n  --dsw-alias-turn-trigger-bg-hover: #e9eef1;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #1b2126;\n  --dsw-alias-tooltip-bg: #23272c;\n  --dsw-alias-tooltip-key-bg: #2d3238;\n  --dsw-alias-menu-icon: #56626b;\n  --dsw-alias-menu-group-header-fill: #4a6b8a0a;\n  --dsw-alias-scrollbar-bg-l1: #24313b33;\n  --dsw-alias-scrollbar-hover-l1: #24313b52;\n  --dsw-alias-scrollbar-bg-l2: #24313b3d;\n  --dsw-alias-scrollbar-hover-l2: #24313b5c;\n\n  --vv-accent: #4a6b8a;\n  --vv-heading: #2f4a63;\n  --vv-heading-soft: #3e5a72;\n  --vv-strong: #12181d;\n  --vv-line: #24313b2b;\n  --vv-line-soft: #24313b1f;\n  --vv-link-underline: #37607f73;\n  --vv-code-bg: #3f64850a;\n  --vv-inline-code-bg: #3f648512;\n  --vv-inline-code-border: #3f64852e;\n  --vv-inline-code-fg: #274a63;\n  --vv-quote-bg: #3f64850a;\n  --vv-table-head: #3f648514;\n  --vv-table-zebra: #24313b08;\n  --vv-marker: #4a6b8a;\n  --vv-selection: #5a7b9a38;\n  --vv-glow: #7fa6c01a;\n  --vv-glow-2: #7f8fb012;\n  --vv-sidebar-fill: #eff2f4;\n  --vv-hover: #2f4a6312;\n  --vv-active: #2f4a6321;\n  --vv-tip: #edf0f2;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n","voltage":"/* ===== DSH Vivid Theme: Voltage =====\n   Generiert von dsh-themes/build.mjs — nicht direkt bearbeiten. */\n\n/* =========================================================================\n   Palette: VOLTAGE  —  Neon-Magenta mit Cyan-Kante auf Tiefindigo\n   Die laute Schwester der Reihe: hohe Saettigung, harte Kanten, klarer\n   Akzent. Fuer kurze, konzentrierte Sessions und Streams.\n   ========================================================================= */\n\n/* ---------- Dunkelmodus ---------- */\nhtml body[data-ds-dark-theme] {\n  /* Flaechen */\n  --dsw-alias-bg-base: #0a0810;\n  --dsw-alias-bg-layer-1: #110d1a;\n  --dsw-alias-bg-layer-2: #181223;\n  --dsw-alias-bg-layer-3: #21182f;\n  --dsw-alias-bg-overlay: #06040bf2;\n  --dsw-alias-bg-mask-1: #06040bb3;\n  --dsw-alias-bg-mask-2: #06040bd9;\n  --dsw-alias-bg-mask-3: #06040bf2;\n  --dsw-alias-bg-skeleton: #1d1630;\n\n  /* Linien */\n  --dsw-alias-border-l1: #ff6ae029;\n  --dsw-alias-border-l2: #ff6ae038;\n  --dsw-alias-border-l3: #ff6ae04d;\n  --dsw-alias-border-l4: #ff6ae06b;\n\n  /* Schrift */\n  --dsw-alias-label-primary: #ece6f5;\n  --dsw-alias-label-primary-bluish: #f0e4fa;\n  --dsw-alias-label-primary-dimmed: #c9bcd9;\n  --dsw-alias-label-secondary: #b0a2c2;\n  --dsw-alias-label-tertiary: #8a7c9c;\n  --dsw-alias-label-caption: #746682;\n  --dsw-alias-label-dimmed: #615470;\n  --dsw-alias-link: #6ee8ff;\n\n  /* Marke + Interaktion */\n  --dsw-alias-brand-primary: #ff5ad4;\n  --dsw-alias-brand-primary-invert: #0a0810;\n  --dsw-alias-brand-text: #ffa8e8;\n  --dsw-alias-interactive-bg-hover: #ff5ad414;\n  --dsw-alias-interactive-bg-active: #ff5ad422;\n  --dsw-alias-interactive-bg-hover-accent: #ff5ad426;\n  --dsw-alias-button-primary-fill: #d63ab0;\n  --dsw-alias-button-primary-hover: #ff5ad4;\n  --dsw-alias-button-ghost-active-fill: #ff5ad41f;\n  --dsw-alias-button-ghost-active-border: #ff5ad447;\n  --dsw-alias-button-ghost-active-hover: #ff5ad42e;\n\n  /* Markdown */\n  --dsw-alias-markdown-code-block: #ff5ad40f;\n  --dsw-alias-markdown-code-block-banner: #ff5ad41a;\n  --dsw-alias-markdown-inline-code: #ff7adc21;\n  --dsw-alias-markdown-citation: #ff5ad43d;\n  --dsw-alias-markdown-tag: #ff5ad42b;\n\n  /* Zustaende */\n  --dsw-alias-state-success-primary: #4ff0b4;\n  --dsw-alias-state-success-secondary: #4ff0b426;\n  --dsw-alias-state-success-tertiary: #4ff0b414;\n  --dsw-alias-state-warn-primary: #ffd166;\n  --dsw-alias-state-warn-label: #ffe08c;\n  --dsw-alias-state-warn-secondary: #ffd16626;\n  --dsw-alias-state-warn-tertiary: #ffd16614;\n  --dsw-alias-state-error-primary: #ff6b8a;\n  --dsw-alias-state-error-secondary: #ff6b8a26;\n  --dsw-alias-state-business-primary: #6ee8ff;\n  --dsw-alias-state-business-tertiary: #6ee8ff26;\n  --dsw-alias-state-idle-primary: #8a7c96;\n\n  /* Chrome */\n  --dsw-alias-settings-card-fill: #130f1e;\n  --dsw-alias-settings-card-stroke: #ff6ae02e;\n  --dsw-alias-turn-trigger-bg: #110d1a;\n  --dsw-alias-turn-trigger-bg-hover: #1b1328;\n  --dsw-alias-toast-bg: #1b1328;\n  --dsw-alias-toast-label: #ece6f5;\n  --dsw-alias-tooltip-bg: #211932;\n  --dsw-alias-tooltip-key-bg: #2e2444;\n  --dsw-alias-menu-icon: #b0a2c2;\n  --dsw-alias-menu-group-header-fill: #ff5ad40f;\n  --dsw-alias-scrollbar-bg-l1: #ff6ae038;\n  --dsw-alias-scrollbar-hover-l1: #ff6ae05c;\n  --dsw-alias-scrollbar-bg-l2: #ff6ae042;\n  --dsw-alias-scrollbar-hover-l2: #ff6ae066;\n\n  /* Vivid-Ebene */\n  --vv-accent: #ff5ad4;\n  --vv-heading: #ffb8ee;\n  --vv-heading-soft: #d9a6e0;\n  --vv-strong: #fdf2ff;\n  --vv-line: #ff6ae033;\n  --vv-line-soft: #ff6ae024;\n  --vv-link-underline: #6ee8ff73;\n  --vv-code-bg: #ff5ad40d;\n  --vv-inline-code-bg: #ff7adc1f;\n  --vv-inline-code-border: #ff96e438;\n  --vv-inline-code-fg: #ffd6f4;\n  --vv-quote-bg: #ff5ad40d;\n  --vv-table-head: #ff5ad41a;\n  --vv-table-zebra: #ffffff08;\n  --vv-marker: #ff5ad4;\n  --vv-selection: #ff5ad44d;\n  --vv-glow: #ff3ac017;\n  --vv-glow-2: #3ae8ff12;\n  --vv-sidebar-fill: #0e0a16;\n  --vv-hover: #ff5ad414;\n  --vv-active: #ff5ad424;\n  --vv-tip: #1c1430;\n}\n\n/* ---------- Hellmodus ---------- */\nhtml body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #fdf7fd;\n  --dsw-alias-bg-layer-1: #ffffff;\n  --dsw-alias-bg-layer-2: #f9edfb;\n  --dsw-alias-bg-layer-3: #f3dff5;\n  --dsw-alias-bg-skeleton: #f7e9fa;\n\n  --dsw-alias-border-l1: #5c1a521f;\n  --dsw-alias-border-l2: #5c1a522e;\n  --dsw-alias-border-l3: #5c1a5242;\n  --dsw-alias-border-l4: #5c1a525c;\n\n  --dsw-alias-label-primary: #241526;\n  --dsw-alias-label-primary-bluish: #2b152f;\n  --dsw-alias-label-secondary: #644f68;\n  --dsw-alias-label-tertiary: #7f6a83;\n  --dsw-alias-label-caption: #947f98;\n  --dsw-alias-label-dimmed: #ad9ab0;\n  --dsw-alias-link: #a5148f;\n\n  --dsw-alias-brand-primary: #c2189f;\n  --dsw-alias-brand-text: #96107c;\n  --dsw-alias-interactive-bg-hover: #c2189f14;\n  --dsw-alias-interactive-bg-active: #c2189f22;\n  --dsw-alias-interactive-bg-hover-accent: #c2189f1f;\n  --dsw-alias-button-primary-fill: #b8149a;\n  --dsw-alias-button-primary-hover: #96107c;\n  --dsw-alias-button-ghost-active-fill: #c2189f1a;\n  --dsw-alias-button-ghost-active-border: #c2189f40;\n  --dsw-alias-button-ghost-active-hover: #c2189f26;\n\n  --dsw-alias-markdown-code-block: #c2189f0d;\n  --dsw-alias-markdown-code-block-banner: #c2189f1a;\n  --dsw-alias-markdown-inline-code: #c2189f14;\n  --dsw-alias-state-success-primary: #0f7a5c;\n  --dsw-alias-state-warn-primary: #a1741a;\n  --dsw-alias-state-error-primary: #c02a52;\n  --dsw-alias-state-business-primary: #2f63c9;\n  --dsw-alias-state-idle-primary: #8a7a8e;\n\n  --dsw-alias-settings-card-fill: #ffffff;\n  --dsw-alias-settings-card-stroke: #5c1a521a;\n  --dsw-alias-turn-trigger-bg: #f9edfb;\n  --dsw-alias-turn-trigger-bg-hover: #f5e2f6;\n  --dsw-alias-toast-bg: #ffffff;\n  --dsw-alias-toast-label: #241526;\n  --dsw-alias-tooltip-bg: #211932;\n  --dsw-alias-tooltip-key-bg: #2e2444;\n  --dsw-alias-menu-icon: #644f68;\n  --dsw-alias-menu-group-header-fill: #c2189f0a;\n  --dsw-alias-scrollbar-bg-l1: #5c1a5233;\n  --dsw-alias-scrollbar-hover-l1: #5c1a5252;\n  --dsw-alias-scrollbar-bg-l2: #5c1a523d;\n  --dsw-alias-scrollbar-hover-l2: #5c1a525c;\n\n  --vv-accent: #c2189f;\n  --vv-heading: #96107c;\n  --vv-heading-soft: #9a3d8c;\n  --vv-strong: #1a0f1c;\n  --vv-line: #5c1a522b;\n  --vv-line-soft: #5c1a521f;\n  --vv-link-underline: #a5148f73;\n  --vv-code-bg: #c2189f0a;\n  --vv-inline-code-bg: #c2189f12;\n  --vv-inline-code-border: #c2189f2e;\n  --vv-inline-code-fg: #75135f;\n  --vv-quote-bg: #c2189f0a;\n  --vv-table-head: #c2189f14;\n  --vv-table-zebra: #5c1a5208;\n  --vv-marker: #c2189f;\n  --vv-selection: #cf3fb238;\n  --vv-glow: #ff4fd81a;\n  --vv-glow-2: #22c8e01a;\n  --vv-sidebar-fill: #fbf0fc;\n  --vv-hover: #96107c12;\n  --vv-active: #96107c21;\n  --vv-tip: #f8e8fa;\n}\n\n\n/* =========================================================================\n   DSH Vivid — gemeinsame Komponenten-Ebene\n   -------------------------------------------------------------------------\n   Diese Datei enthaelt KEINE Farbwerte. Sie liest ausschliesslich die\n   --vv-* Variablen, die jede Palette definiert, und die offiziellen\n   --dsw-* Tokens des Harness. Dadurch ergibt jede Palette automatisch ein\n   stimmiges Gesamtbild.\n   -------------------------------------------------------------------------\n   Selektoren sind absichtlich spezifischer als die Harness-Stylesheets\n   (html body[...] = 0,0,1,2 bzw. 0,0,0,2) und laufen deshalb auch dann,\n   wenn die Runtime-Styles spaeter im Dokument eingefuegt werden.\n   ========================================================================= */\n\n/* ---------- 1. Lese-Komfort: Rhythmus, Auswahl, Fokus ---------- */\n\nhtml body {\n  /* Etwas mehr Luft zwischen den Zeilen nimmt den harten Kontrast raus. */\n  --dsw-font-markdown-base-line-height: 1.7;\n  --dsw-font-markdown-small-line-height: 1.6;\n  --dsh-content-letter-spacing: 0.012em;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Sanfter Farb-Glow oben links: nimmt dem fast schwarzen Canvas die Haerte. */\nhtml body {\n  background-image: radial-gradient(\n      1200px 520px at 0% -10%,\n      var(--vv-glow) 0%,\n      transparent 62%\n    ),\n    radial-gradient(900px 420px at 100% 0%, var(--vv-glow-2) 0%, transparent 60%);\n  background-attachment: fixed;\n  background-repeat: no-repeat;\n}\n\nhtml body ::selection {\n  background: var(--vv-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 2. Prosa: Ueberschriften ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3,\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h4 {\n  color: var(--vv-heading);\n  letter-spacing: 0.005em;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h1 {\n  padding-bottom: 0.3em;\n  border-bottom: 1px solid var(--vv-line);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h2 {\n  padding-left: 10px;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 2px;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) h3 {\n  color: var(--vv-heading-soft);\n}\n\n/* ---------- 3. Prosa: Hervorhebungen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) strong {\n  color: var(--vv-strong);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) em {\n  color: var(--vv-heading-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a {\n  color: var(--dsw-alias-link);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n  text-decoration-color: var(--vv-link-underline);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) a:hover {\n  color: var(--vv-accent);\n  text-decoration-color: currentColor;\n}\n\n/* ---------- 4. Prosa: Inline-Code als Chip ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :not(pre) > code {\n  padding: 0.1em 0.4em;\n  border: 1px solid var(--vv-inline-code-border);\n  border-radius: 6px;\n  background: var(--vv-inline-code-bg);\n  color: var(--vv-inline-code-fg);\n  font-weight: 500;\n  white-space: break-spaces;\n}\n\n/* ---------- 5. Prosa: Codebloecke ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre {\n  border: 1px solid var(--vv-line);\n  border-radius: 12px;\n  background: var(--vv-code-bg);\n  box-shadow: inset 0 1px 0 var(--vv-line-soft);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) pre code {\n  background: none;\n  border: 0;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* ---------- 6. Prosa: Zitate ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote {\n  margin: 0.85em 0;\n  padding: 0.6em 0.95em;\n  border-left: 3px solid var(--vv-accent);\n  border-radius: 0 10px 10px 0;\n  background: var(--vv-quote-bg);\n  color: var(--dsw-alias-label-secondary);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :first-child {\n  margin-top: 0;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* ---------- 7. Prosa: Tabellen ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  border: 1px solid var(--vv-line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) thead th {\n  background: var(--vv-table-head);\n  color: var(--dsw-alias-label-primary);\n  font-weight: 620;\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) tbody tr:nth-child(even) {\n  background: var(--vv-table-zebra);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) :is(th, td) {\n  border-color: var(--vv-line-soft);\n}\n\n/* ---------- 8. Prosa: Listen, Trennlinien ---------- */\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) li::marker {\n  color: var(--vv-marker);\n}\n\n:is([data-conversation-content], [data-conversation-scroll], [data-conversation-region]) hr {\n  height: 1px;\n  margin: 1.25em 0;\n  border: 0;\n  background: linear-gradient(90deg, transparent, var(--vv-line), transparent);\n}\n\n/* ---------- 9. Chrome: Sidebar, Menues, Karten ---------- */\n\nhtml body {\n  --dsw-specific-sidebar-fill: var(--vv-sidebar-fill);\n  --dsw-specific-sidebar-nav-item-hover: var(--vv-hover);\n  --dsw-specific-sidebar-nav-item-active: var(--vv-active);\n  --dsw-specific-sidebar-nav-item-active-accent: var(--vv-accent);\n  --dsw-specific-tip: var(--vv-tip);\n}\n\n/* Fokusring in der Akzentfarbe statt im Standardblau. */\nhtml body {\n  --dsw-focus-ring-color: var(--vv-accent);\n}\n\n/* ---------- 10. Statuszeilen farblich lesbar ---------- */\n\nhtml body [data-status='error'],\nhtml body [data-state='error'] {\n  --dsw-alias-label-primary: var(--dsw-alias-state-error-primary);\n}\n\n/* ---------- 11. Druck ---------- */\n@media print {\n  html body {\n    background-image: none;\n  }\n}\n\n"}
    const ORDER = [
      "aurora", "ember", "mint", "sakura", "iris", "slate",
      "moss", "crimson", "arctic", "voltage", "sand", "noir",
    ]
    const LABELS = {
      aurora: "Aurora", ember: "Ember", mint: "Mint", sakura: "Sakura", iris: "Iris", slate: "Slate",
      moss: "Moss", crimson: "Crimson", arctic: "Arctic", voltage: "Voltage", sand: "Sand", noir: "Noir",
    }
    const STORAGE_KEY = "dsh-theme-vivid.palette"
    const STYLE_ID = "dsh-theme-vivid-runtime"

    function stored() {
      try {
        return window.localStorage.getItem(STORAGE_KEY)
      } catch (error) {
        return null
      }
    }

    function remember(id) {
      try {
        window.localStorage.setItem(STORAGE_KEY, id)
      } catch (error) {
        /* privater Modus o. ae. — Auswahl gilt dann nur fuer diese Sitzung */
      }
    }

    function currentId() {
      const id = stored()
      return typeof id === "string" && Object.prototype.hasOwnProperty.call(THEMES, id) ? id : "aurora"
    }

    /** Setzt den Laufzeit-Style-Block; spaeter im Dokument = gewinnt gegen die Host-Injection. */
    function paint(id) {
      const css = THEMES[id]
      if (typeof css !== "string") return
      let node = document.getElementById(STYLE_ID)
      if (!node) {
        node = document.createElement("style")
        node.id = STYLE_ID
        document.head.appendChild(node)
      }
      node.textContent = css
    }

    const inject = ["slots"]

    function apply(ctx) {
      const h = React.createElement
      paint(currentId())

      const base = {
        padding: "6px 14px",
        borderRadius: 8,
        border: "1px solid var(--dsw-alias-border-l2, #8884)",
        background: "var(--dsw-alias-bg-layer-2, transparent)",
        color: "var(--dsw-alias-label-primary, inherit)",
        fontSize: 13,
        cursor: "pointer",
      }
      const selected = {
        borderColor: "var(--dsw-alias-brand-primary, #7ca8ff)",
        background: "var(--dsw-alias-interactive-bg-active, #7ca8ff22)",
        color: "var(--dsw-alias-brand-text, inherit)",
      }

      function PaletteRow() {
        const [active, setActive] = React.useState(currentId())
        const choose = (id) => {
          paint(id)
          remember(id)
          setActive(id)
        }
        return h("div", {
          style: {
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 12,
            padding: "6px 0",
          },
        }, [
          h("div", {
            key: "label",
            style: { color: "var(--dsw-alias-label-primary, inherit)", fontSize: 14 },
          }, "Color theme"),
          h("div", { key: "row", style: { display: "flex", flexWrap: "wrap", justifyContent: "flex-end", gap: 8, maxWidth: "72%" } },
            ORDER.map((id) => h("button", {
              key: id,
              type: "button",
              "aria-pressed": active === id,
              onClick: () => choose(id),
              style: active === id ? Object.assign({}, base, selected) : base,
            }, LABELS[id])),
          ),
        ])
      }

      ctx.slots.inject("settings.general.item", () => ctx.slots.register({
        name: "settings.general.item",
        id: "theme-vivid.palette",
        order: 12,
        inject: () => ({}),
      }, PaletteRow))
    }

    exports.apply = apply
    exports.inject = inject
    return module.exports
  },
})
